import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { assembleHkiiPackage } from './hkii-package.mjs';
import { hashPackage } from '../../lib/lesson/schema.js';
import { validateLessonPackage } from '../../lib/lesson/validate.js';
import { normalizeExamInput } from '../../lib/exam/validate.js';
import { parseExamLines } from '../../lib/exam/parse.js';
const R = String.raw, base = new URL('../../', import.meta.url);
const read = path => JSON.parse(readFileSync(new URL(path, base), 'utf8'));
const ppct = read('tasks/r23-hkii/ppct-hkii.json').grades.find(row => row.grade === 11);
const hkiBankText = readFileSync(new URL('tasks/r22/g11-practice-bank.json',base),'utf8');
const sourceBank = JSON.parse(hkiBankText);
const frozenHkiGeneratorSha256 = 'd1951060182d4b4ba6754bf6b25e8837a14d6171bc3296544cef3ea6af16eeab';
// Frozen pure HKI question generators preserve cumulative coverage without running the HKI writer.
const n=s=>2+(s%13), frac=(a,b)=>R`\frac{${a}}{${b}}`, math=x=>`$${x}$`;
let numericChecks=0;
function numeric(prompt,key,solution,hints,independent){
 assert.ok(Number.isFinite(key)&&Number.isFinite(independent));
 assert.ok(Math.abs(key-independent)<1e-8,`${prompt}: ${key} != ${independent}`);numericChecks++;
 return {type:'closed',prompt,evaluation:{checkerId:'numeric_exact',answerKey:key},solution,hints};
}
function choice(prompt,labels,correct,solution,hints){
 assert.ok(labels.length>=2&&correct>=0&&correct<labels.length);
 return {type:'closed',prompt,inputSchema:{options:labels.map((label,i)=>({id:`o${i+1}`,label}))},evaluation:{checkerId:'choice_exact',answerKey:`o${correct+1}`},solution,hints};
}
function open(prompt,solution,hints,criteria=['Nêu đúng kết luận, đủ điều kiện và lập luận.']){
 return {type:'open',prompt,evaluation:{rubric:{criteria,lookFor:[solution]}},solution,hints};
}
const hints=(read,strategy,first,example)=>[read,strategy,first,example];
const concept=(title,statement,unit,lo,teach,error,question)=>({title,statement,unit,lo,teach,error,question});
const bank={
 radian:concept('Góc lượng giác và radian','Đổi độ sang radian, giải thích số vòng quay và tính độ dài cung theo góc ở tâm.',1,[1],R`Vẽ đường tròn bán kính $r$, đánh dấu chiều dương. Chốt $180^\circ=\pi$ rad, độ dài cung $l=r\alpha$ khi $\alpha$ tính bằng radian; không nhân trực tiếp với số đo độ.`, 'Nhầm đơn vị độ với radian; coi mọi góc cùng điểm cuối có cùng số đo.',(s,d)=>{
  const k=n(s),r=3+s%5;
  if(d===0)return numeric(`Góc quay ${math(`${30*k}^\\circ`)} bằng ${math('a\\pi')} rad. Tìm ${math('a')}.`,k/6,R`$a=${30*k}/180=${frac(k,6)}$.`,hints('Xác định đơn vị đang cho.','Dùng tỉ lệ giữa một nửa vòng và radian.','Chia số đo độ cho 180 để tìm hệ số.','Ví dụ khác: $90^\\circ$ là một nửa của $180^\\circ$.'),30*k*Math.PI/180/Math.PI);
  return numeric(`Một bánh xe bán kính ${r} cm quay góc ${math(`${k}\\pi/6`)} rad. Độ dài cung quét được bằng ${math('b\\pi')} cm. Tìm ${math('b')}.`,r*k/6,R`$l=r\alpha=${r}\cdot ${frac(k,6)}\pi$, nên $b=${frac(r*k,6)}$.`,hints('Góc đã ở đơn vị radian.','Độ dài cung tỉ lệ với góc quay.','Viết công thức độ dài cung rồi thay bán kính.','Ví dụ khác: nửa vòng tròn có độ dài bằng nửa chu vi.'),2*Math.PI*r*(k*Math.PI/6)/(2*Math.PI)/Math.PI);
 }),
 trigValue:concept('Giá trị lượng giác trên đường tròn','Tính giá trị lượng giác của góc, dùng tọa độ điểm trên đường tròn và dấu theo góc phần tư.',1,[1],R`Vẽ đường tròn đơn vị; điểm cuối $M=(\cos\alpha;\sin\alpha)$. Dùng hoành độ/tung độ để xác định dấu; chỉ lập $\tan\alpha$ khi $\cos\alpha\ne0$.`, 'Đổi vị trí sin và cos; bỏ điều kiện của tan.',(s,d)=>{
  const k=n(s),a=5+2*k,b=(a*a-1)/2,c=(a*a+1)/2,sgn=s%2?-1:1;
  return numeric(`Điểm cuối góc ${math('\\alpha')} trên đường tròn đơn vị có tọa độ ${math(`M(${sgn*a}/${c};${b}/${c})`)}. Tính ${math(d===0?'\\cos\\alpha':d===1?'\\sin\\alpha':'\\tan\\alpha')}.`,d===0?sgn*a/c:d===1?b/c:b/(sgn*a),d===0?R`Cosin là hoành độ: $\cos\alpha=${frac(sgn*a,c)}$.`:d===1?R`Sin là tung độ: $\sin\alpha=${frac(b,c)}$.`:R`$\tan\alpha=\sin\alpha/\cos\alpha=${frac(b,sgn*a)}$; hoành độ khác không.`,hints('Đọc rõ hoành độ và tung độ.','Liên hệ từng tọa độ với giá trị lượng giác.','Đánh dấu điểm trên hệ trục trước khi tính.','Ví dụ khác: điểm trên nửa trên đường tròn có tung độ dương.'),d===0?Math.cos(Math.atan2(b,sgn*a)):d===1?Math.sin(Math.atan2(b,sgn*a)):Math.tan(Math.atan2(b,sgn*a)));
 }),
 identity:concept('Quan hệ giữa các giá trị lượng giác','Dùng hệ thức cơ bản và dấu góc phần tư để tìm giá trị lượng giác còn lại.',1,[1],R`Từ đường tròn đơn vị suy ra $\sin^2x+\cos^2x=1$. Khi lấy căn phải xét dấu; từ $\sin x$ chưa thể quyết định dấu của $\cos x$ nếu thiếu vị trí góc.`, 'Lấy căn dương bất kể góc phần tư.',(s,d)=>{
  const a=2*n(s)+1,b=(a*a-1)/2,c=(a*a+1)/2,neg=d%2===1;
  return numeric(`Biết ${math(`\\sin x=${b}/${c}`)}, ${math(neg?'\\pi/2<x<\\pi':'0<x<\\pi/2')}. Tính ${math('\\cos x')}.`,(neg?-a:a)/c,R`$\cos^2x=1-${frac(b*b,c*c)}=${frac(a*a,c*c)}$. Xét góc phần tư, $\cos x=${frac(neg?-a:a,c)}$.`,hints('Xem khoảng chứa góc để xác định dấu.','Dùng hệ thức giữa bình phương sin và cos.','Tính bình phương giá trị chưa biết, chưa chọn dấu vội.','Ví dụ khác: trong góc phần tư II, hoành độ âm.'),(neg?-1:1)*Math.sqrt(1-(b/c)**2));
 }),
 opposite:concept('Góc đối nhau và góc phụ nhau','Biến đổi giá trị lượng giác của hai góc đối nhau hoặc phụ nhau.',1,[1],R`So sánh hai điểm đối xứng qua trục hoành: cos không đổi, sin đổi dấu. Với góc phụ nhau, vai trò sin/cos đổi chỗ. Chốt $\sin(-x)=-\sin x$, $\cos(\pi/2-x)=\sin x$.`, 'Đổi dấu mọi hàm khi đổi góc đối.',(s,d)=>{
  const k=n(s),v=k/(k+2),expr=d%2?R`\cos(\pi/2-x)`:R`\sin(-x)`;
  return numeric(`Biết ${math(`\\sin x=${k}/${k+2}`)}. Tính ${math(expr)}.`,(d%2?1:-1)*v,R`${math(expr)} bằng ${math(d%2?'\\sin x':'-\\sin x')}, nên kết quả ${math(`${d%2?k:-k}/${k+2}`)}.`,hints('Phân biệt góc đối với góc phụ.','Dùng đối xứng đường tròn lượng giác.','Viết giá trị cần tìm theo sin của góc đã biết.','Ví dụ khác: góc $-30^\\circ$ nằm dưới trục hoành.'),d%2?Math.cos(Math.PI/2-Math.asin(v)):Math.sin(-Math.asin(v)));
 }),
 supplement:concept('Góc bù nhau và hơn kém pi','Biến đổi sin, cos của góc bù hoặc góc hơn kém pi; giữ đúng dấu.',1,[1],R`Vẽ điểm cuối góc $x$, $\pi-x$, $\pi+x$. Đối xứng qua trục tung giữ tung độ, đổi hoành độ; qua tâm đổi cả hai tọa độ.`, 'Nhầm góc bù với góc hơn kém pi.',(s,d)=>{
  const k=n(s),v=k/(k+3),expr=d%2?R`\cos(\pi-x)`:R`\sin(\pi+x)`,given=d%2?'\\cos x':'\\sin x';
  return numeric(`Biết ${math(`${given}=${k}/${k+3}`)}. Tính ${math(expr)}.`,-v,R`${math(expr)} bằng ${math(`-${given}`)}, kết quả ${math(`-${k}/${k+3}`)}.`,hints('Xác định phép đối xứng tương ứng.','Theo dõi tọa độ biểu diễn hàm đang hỏi.','Chỉ thay số sau khi đã viết quan hệ dấu.','Ví dụ khác: điểm đối xứng qua tâm có cả hai tọa độ đổi dấu.'),d%2?Math.cos(Math.PI-Math.acos(v)):Math.sin(Math.PI+Math.asin(v)));
 }),
 addition:concept('Công thức cộng','Áp dụng công thức cộng sin, cos để tính giá trị hoặc rút gọn biểu thức.',1,[1],R`Khai triển $\sin(a+b)=\sin a\cos b+\cos a\sin b$ và $\cos(a+b)=\cos a\cos b-\sin a\sin b$. Kiểm bằng $b=0$; lưu ý sin của tổng không là tổng hai sin.`, 'Thiếu tích chéo hoặc nhầm dấu trừ trong cos tổng.',(s,d)=>{
  const a=15+15*(s%11),b=90-a,cos=d%2===1;
  return numeric(`Tính ${math(cos?`\\cos ${a}^\\circ\\cos ${b}^\\circ-\\sin ${a}^\\circ\\sin ${b}^\\circ`:`\\sin ${a}^\\circ\\cos ${b}^\\circ+\\cos ${a}^\\circ\\sin ${b}^\\circ`)}.`,cos?0:1,R`Nhận ra công thức ${cos?'cos':'sin'} tổng: ${math(`${cos?'\\cos':'\\sin'}(${a}^\\circ+(${b}^\\circ))=${cos?'\\cos':'\\sin'}90^\\circ=${cos?0:1}`)}.`,hints('Giữ nguyên từng tích và dấu giữa chúng.','Tìm cấu trúc công thức cộng.','Cộng hai góc sau khi nhận đúng hàm.','Ví dụ khác: thay một góc bằng $0^\\circ$ để kiểm công thức.'),cos?Math.cos(a*Math.PI/180)*Math.cos(b*Math.PI/180)-Math.sin(a*Math.PI/180)*Math.sin(b*Math.PI/180):Math.sin(a*Math.PI/180)*Math.cos(b*Math.PI/180)+Math.cos(a*Math.PI/180)*Math.sin(b*Math.PI/180));
 }),
 double:concept('Nhân đôi và hạ bậc','Dùng công thức nhân đôi, hạ bậc để tính và biến đổi lượng giác.',1,[1],R`Đặt $a=b=x$ trong công thức cộng để có $\sin2x=2\sin x\cos x$, $\cos2x=1-2\sin^2x$. Suy ra công thức hạ bậc; phân biệt $\sin^2x$ với $\sin2x$.`, 'Quên hệ số hai hoặc nhầm bình phương với góc nhân đôi.',(s,d)=>{
  const k=n(s),v=k/(k+2);
  if(d%2)return numeric(`Biết ${math(`\\cos 2x=${k}/${k+2}`)}. Tính ${math('\\sin^2x')}.`,(1-v)/2,R`$\sin^2x=(1-\cos2x)/2=${frac(1,k+2)}$.`,hints('Đây là bình phương sin, không phải sin của góc đôi.','Dùng công thức hạ bậc.','Chuyển từ cos góc đôi sang bình phương sin.','Ví dụ khác: với $x=0$, bình phương sin bằng không.'),Math.sin(Math.acos(v)/2)**2);
  return numeric(`Biết ${math(`\\sin x=${k}/${k+2}`)}. Tính ${math('\\cos2x')}.`,1-2*v*v,R`$\cos2x=1-2\sin^2x=1-2(${frac(k,k+2)})^2$.`,hints('Chọn công thức chỉ cần sin của góc.','Biến đổi cos góc đôi theo bình phương sin.','Bình phương phân số trước khi nhân hệ số.','Ví dụ khác: $\\cos0=1$ giúp kiểm dấu hằng số.'),Math.cos(2*Math.asin(v)));
 }),
 productSum:concept('Tích thành tổng, tổng thành tích','Nhận dạng và sử dụng công thức biến đổi tích thành tổng hoặc tổng thành tích.',1,[1],R`Ghép công thức cộng/trừ để suy ra $2\sin a\cos b=\sin(a+b)+\sin(a-b)$. Chốt công thức tổng hai sin theo nửa tổng/nửa hiệu; không bỏ hệ số hai.`, 'Đảo nửa tổng và nửa hiệu; bỏ hệ số hai.',(s,d)=>{
  const k=n(s),a=`${k}x`,b=`${k+2}x`;
  return open(d%2?`Viết ${math(`\\sin(${a})+\\sin(${b})`)} thành tích; nêu nửa tổng và nửa hiệu hai góc.`:`Viết ${math(`2\\sin(${a})\\cos(${b})`)} thành tổng; giải thích dấu của góc hiệu.`,d%2?R`Nửa tổng là $${k+1}x$, nửa hiệu là $-x$; biểu thức bằng $2\sin(${k+1}x)\cos x$.`:R`Bằng $\sin(${2*k+2}x)+\sin(-2x)=\sin(${2*k+2}x)-\sin2x$.`,hints('Ghi hai góc riêng, không coi hệ số là giá trị hàm.','Dùng công thức tổng/tích phù hợp dạng ban đầu.','Tính tổng và hiệu hai góc trước.','Ví dụ khác: nửa tổng của $3t$ và $7t$ là $5t$.'),['Biến đổi đúng biểu thức.','Giữ đúng hệ số và xử lý góc âm.']);
 }),
 trigDomain:concept('Tập xác định, tập giá trị','Xác định tập xác định và tập giá trị của hàm lượng giác đơn giản.',1,[2],R`Từ phân số $\tan x=\sin x/\cos x$, loại điểm làm mẫu bằng không. Đồ thị sin/cos có tung độ từ $-1$ đến $1$; dịch và co giãn tung độ cho hàm mới.`, 'Nhầm tập xác định với tập giá trị; quên điều kiện mẫu.',(s,d)=>{
  const a=n(s),b=1+s%5;
  if(d===0)return numeric(`Hàm số ${math(`y=${a}+${b}\\sin x`)} có giá trị lớn nhất bằng bao nhiêu?`,a+b,R`$-1\le\sin x\le1$, nên $y\le${a+b}$, đạt khi $\sin x=1$.`,hints('Xác định khoảng giá trị của sin.','Biến đổi hai đầu mút theo phép nhân và cộng.','Vì hệ số sin dương, xét đầu mút lớn hơn.','Ví dụ khác: thêm một hằng số dịch toàn bộ khoảng giá trị.'),a+b*Math.sin(Math.PI/2));
  return open(`Tìm tập xác định của ${math(`y=\\tan(${a}x)`)} và tập giá trị của ${math(`z=${a}+${b}\\cos x`)}.`,R`Điều kiện $\cos(${a}x)\ne0$, tức $x\ne\frac{\pi}{${2*a}}+\frac{k\pi}{${a}}$, $k\in\mathbb Z$. Tập giá trị của $z$ là $[${a-b};${a+b}]$.`,hints('Hai yêu cầu thuộc hai hàm khác nhau.','Với tan, xét mẫu; với cos, xét biên độ.','Viết điều kiện cos khác không trước khi giải theo biến.','Ví dụ khác: tập giá trị của $2\\cos t$ là $[-2;2]$.'));
 }),
 parity:concept('Chẵn, lẻ và tuần hoàn','Kiểm tra tính chẵn/lẻ và xác định chu kỳ của hàm lượng giác cơ bản.',1,[2],R`Trước khi xét $f(-x)$, kiểm miền xác định đối xứng. So sánh với $f(x)$ và $-f(x)$. Chu kỳ của $\sin(ax)$ là $2\pi/|a|$, của $\tan(ax)$ là $\pi/|a|$.`, 'Chỉ nhìn sin/cos rồi bỏ hằng số cộng; nhầm chu kỳ tan và sin.',(s,d)=>{
  const a=n(s),b=1+s%4;
  return open(`Xét tính chẵn/lẻ và chu kỳ dương nhỏ nhất của ${math(d%2?`f(x)=${b}\\cos(${a}x)`:`f(x)=${b}\\sin(${a}x)`)}.`,R`Miền xác định là $\mathbb R$. $f(-x)=${d%2?'f(x)':'-f(x)'}$, nên hàm ${d%2?'chẵn':'lẻ'}. Chu kỳ $T=2\pi/${a}$.`,hints('Thay biến bằng số đối ở toàn bộ biểu thức.','Dùng tính đối xứng của sin hoặc cos.','Viết phương trình để góc tăng một vòng.','Ví dụ khác: nhân giá trị hàm với hằng số không đổi chu kỳ.'));
 }),
 sinCosGraph:concept('Đồ thị sin và cos','Đọc chu kỳ, biên độ, điểm đặc biệt và chiều biến thiên của sin/cos.',1,[2],R`Lập bảng tại năm mốc của một chu kỳ, nối thành đường cong. Xác định khoảng tăng/giảm bằng đường tròn, không suy từ một điểm.`, 'Đồng nhất biên độ với chu kỳ; kết luận tăng trên toàn miền.',(s,d)=>{
  const a=n(s),b=1+s%4;
  return open(R`Xét $y=${b}\sin(${a}x)$ và $z=${b}\cos(${a}x)$. Nêu chu kỳ, biên độ; lập bảng giá trị của cả hai hàm tại $x=0,\pi/${2*a},\pi/${a}${d===0?'':R`,3\pi/${2*a},2\pi/${a}`}$ rồi phác hai đồ thị trên cùng hệ trục. Trên $(0;\pi/${2*a})$, mỗi hàm tăng hay giảm?`,R`Cả hai có chu kỳ $T=2\pi/${a}$, biên độ ${b}. Các giá trị của y là $0,${b},0${d===0?'':`,-${b},0`}$; của z là $${b},0,-${b}${d===0?'':`,0,${b}`}$, tại đúng các mốc đã cho. Trên $(0;\pi/${2*a})$, y tăng từ 0 đến ${b}, z giảm từ ${b} về 0. Đồ thị cos bắt đầu tại cực đại; đồ thị sin bắt đầu tại gốc và đi lên.`,hints('Đổi mỗi hoành độ thành góc chung của sin và cos.','Sin là tung độ, cos là hoành độ trên đường tròn đơn vị.','Tính cả hai hàm tại mốc đầu tiên rồi lần lượt chuyển góc một phần tư vòng.','Ví dụ khác: trên cung từ góc 0 đến pi/2, tung độ tăng còn hoành độ giảm.'),['Chu kỳ, biên độ và cả hai hàng giá trị đúng.','Phác đúng hai đường qua các điểm, phân biệt chiều biến thiên của sin và cos.']);
 }),
 tanCotGraph:concept('Đồ thị tan và cot','Xác định miền, chu kỳ, chiều biến thiên của tan/cot trên khoảng liên tục.',1,[2],R`Đánh dấu các điểm bị loại trước khi vẽ nhánh. Tan tăng trên mỗi khoảng giữa hai điểm bị loại; cot giảm trên mỗi khoảng tương ứng. Không nối qua điểm không xác định.`, 'Vẽ đường nối qua tiệm cận; dùng chu kỳ hai pi cho tan.',(s,d)=>{
  const a=n(s),isTan=d%2===0;
  return open(`Với ${math(`y=${isTan?'\\tan':'\\cot'}(${a}x)`)}: nêu chu kỳ, các giá trị bị loại và một khoảng mà hàm tăng hoặc giảm.`,isTan?R`$T=\pi/${a}$; loại $x=\pi/${2*a}+k\pi/${a}$. Hàm tăng trên $(-\pi/${2*a};\pi/${2*a})$.`:R`$T=\pi/${a}$; loại $x=k\pi/${a}$. Hàm giảm trên $(0;\pi/${a})$.`,hints('Viết sin hoặc cos ở mẫu của hàm.','Tìm những góc làm mẫu bằng không.','Chọn một nhánh giữa hai điểm bị loại.','Ví dụ khác: nhánh cot cơ bản nằm giữa $0$ và $\\pi$.'));
 }),
 sinEquation:concept('Phương trình sin','Giải phương trình sin cơ bản, ghi đủ họ nghiệm và lọc nghiệm trong khoảng.',1,[2],R`Vẽ đường thẳng ngang cắt đường tròn ở hai điểm. Nếu $\sin x=\sin a$, nghiệm là $x=a+2k\pi$ hoặc $x=\pi-a+2k\pi$. Kiểm điều kiện giá trị nằm trong $[-1;1]$.`, 'Chỉ ghi một họ nghiệm hoặc sai chu kỳ.',(s,d)=>{
  const a=n(s);
  return open(`Giải phương trình ${math(`\\sin(${a}x)=\\frac12`)}${d>=2?`; tìm nghiệm trong ${math(`[0;\\pi/${a}]`)}.`:'.'}, ghi rõ ${math('k\\in\\mathbb Z')}.`,R`$x=\pi/${6*a}+2k\pi/${a}$ hoặc $x=5\pi/${6*a}+2k\pi/${a}$.${d>=2?R` Trong đoạn đã cho chỉ có $\pi/${6*a}$ và $5\pi/${6*a}$.`:''}`,hints('Xét góc trong sin như một ẩn phụ.','Dùng hai vị trí có cùng tung độ trên đường tròn.','Tìm nghiệm của ẩn góc rồi chia toàn bộ cho hệ số.','Ví dụ khác: sin của $30^\\circ$ và $150^\\circ$ bằng nhau.'),['Đủ hai họ nghiệm với tham số nguyên.','Chia đúng mọi số hạng; lọc khoảng nếu được yêu cầu.']);
 }),
 cosEquation:concept('Phương trình cos','Giải phương trình cos cơ bản, dùng đối xứng và điều kiện nghiệm.',1,[2],R`Nếu $\cos x=\cos a$ thì $x=\pm a+2k\pi$. Hai góc có cùng hoành độ đối xứng qua trục hoành; không thay bằng công thức của sin.`, 'Nhầm dấu cộng/trừ với hai họ nghiệm sin.',(s,d)=>{
  const a=n(s);
  return open(`Giải ${math(`\\cos(${a}x)=-\\frac12`)}${d>=2?`; liệt kê nghiệm thuộc ${math(`[0;2\\pi/${a})`)}.`:'.'}`,R`$x=\pm2\pi/${3*a}+2k\pi/${a}$, $k\in\mathbb Z$.${d>=2?R` Trong khoảng đã cho: $2\pi/${3*a}$ và $4\pi/${3*a}$.`:''}`,hints('Tìm góc có cos bằng giá trị đang cho.','Dùng hai điểm cùng hoành độ.','Đặt góc bên trong làm ẩn phụ.','Ví dụ khác: hai góc đối nhau có cùng cosin.'));
 }),
 tanEquation:concept('Phương trình tan và cot','Giải phương trình tan/cot và giữ điều kiện xác định.',1,[2],R`Chu kỳ tan và cot bằng $\pi$. Với $\tan u=\tan a$ hoặc $\cot u=\cot a$, nghiệm $u=a+k\pi$; kiểm mẫu lượng giác khác không.`, 'Dùng chu kỳ hai pi làm mất nghiệm.',(s,d)=>{
  const a=n(s),cot=d%2===1;
  return open(`Giải ${math(`${cot?'\\cot':'\\tan'}(${a}x)=1`)}. Giải thích vì sao bước giữa hai nghiệm liên tiếp không phải ${math(`2\\pi/${a}`)}.`,R`$${a}x=\pi/4+k\pi$, nên $x=\pi/${4*a}+k\pi/${a}$; các nghiệm đều thuộc miền xác định. Chu kỳ của hàm là $\pi$ theo biến góc.`,hints('Kiểm điều kiện mẫu của hàm.','Nhớ chu kỳ của tan/cot.','Giải theo góc rồi chia hệ số.','Ví dụ khác: tang của hai góc hơn kém $\\pi$ bằng nhau.'));
 }),
 sequence:concept('Dãy số và cách cho dãy số','Phân biệt dãy hữu hạn/vô hạn; chuyển giữa mô tả, liệt kê, công thức và truy hồi.',1,[3],R`Đặt mỗi số hạng vào vị trí nguyên dương. So sánh danh sách số ghế trong một phòng có hữu hạn hàng với mô hình tăng mãi. Viết cùng quy luật bằng lời, liệt kê, công thức và truy hồi.`, 'Không nêu miền chỉ số; xem dấu ba chấm là đủ chứng minh vô hạn.',(s)=>{
  const a=n(s),b=1+s%4,N=6+s%8;
  return open(`Một khán phòng có ${N} hàng; hàng đầu ${a} ghế, mỗi hàng sau thêm ${b} ghế. Liệt kê ba số hạng đầu; viết công thức theo ${math('n')} và truy hồi kèm miền chỉ số. Nếu bỏ giới hạn số hàng, dãy thay đổi thế nào?`,R`Ba số hạng: $${a},${a+b},${a+2*b}$. $u_n=${a}+${b}(n-1)$ với $1\le n\le${N}$; $u_1=${a}$, $u_{n+1}=u_n+${b}$ với $1\le n<${N}$. Mô hình không giới hạn dùng $n\in\mathbb N^*$ và là dãy vô hạn.`,hints('Tách quy luật với số vị trí được phép.','Viết số ghế hàng đầu trước khi tính hàng kế.','Đếm số lần thêm từ hàng đầu tới hàng thứ n.','Ví dụ khác: danh sách bảy ngày có bảy vị trí dù quy luật lịch tiếp tục.'),['Đủ bốn cách biểu diễn và đúng chỉ số.','Phân biệt hữu hạn với mô hình vô hạn.']);
 }),
 monotone:concept('Tăng, giảm và bị chặn','Xét tính đơn điệu và tìm chặn của dãy từ công thức; không suy từ vài số hạng.',1,[3],R`Xét dấu $u_{n+1}-u_n$, sau đó tìm bất đẳng thức đúng với mọi chỉ số. Dãy tăng vẫn có thể bị chặn.`, 'Kết luận tăng chỉ vì ba số hạng đầu tăng; nhầm tăng với không bị chặn.',(s,d)=>{
  const a=n(s),b=1+s%5,sgn=d%2?1:-1;
  return open(`Cho ${math(`u_n=${a}${sgn>0?'+':'-'}\\frac{${b}}{n+1}`)}, ${math('n\\ge1')}. Xét tăng/giảm và nêu một chặn dưới, một chặn trên.`,R`$u_{n+1}-u_n=${sgn>0?'-':''}${b}/((n+1)(n+2))$, nên dãy ${sgn>0?'giảm':'tăng'}. ${sgn>0?`$${a}<u_n\\le${a+b/2}$`:`$${a-b/2}\\le u_n<${a}$`}.`,hints('Viết số hạng kế tiếp bằng cách thay toàn bộ chỉ số.','Xét hiệu hai số hạng liên tiếp.','Quy đồng hai phân số trước khi xét dấu.','Ví dụ khác: với $n\\ge1$, ta có $0<1/(n+1)\\le1/2$.'));
 }),
 arithmetic:concept('Số hạng cấp số cộng','Nhận biết cấp số cộng; dùng số hạng đầu và công sai để tìm số hạng hoặc chỉ số.',1,[3],R`Lập bảng số lần cộng: từ $u_1$ đến $u_n$ có $n-1$ bước. Chốt $u_n=u_1+(n-1)d$.`, 'Dùng n lần cộng; đổi công sai khi gặp số âm.',(s)=>{
  const a=n(s),step=1+s%5,N=6+s%7,key=a+(N-1)*step;
  return numeric(`Cấp số cộng có ${math(`u_1=${a}`)}, ${math(`d=${step}`)}. Tính ${math(`u_{${N}}`)}.`,key,R`$u_{${N}}=${a}+(${N}-1)\cdot${step}=${key}$.`,hints('Đếm vị trí bắt đầu từ một.','Số lần cộng ít hơn số thứ tự một đơn vị.','Viết số hạng đầu rồi cộng các bước.','Ví dụ khác: từ số hạng thứ nhất đến thứ tư có ba bước.'),Array.from({length:N},(_,i)=>a+i*step).at(-1));
 }),
 arithmeticSum:concept('Tổng cấp số cộng','Tính tổng cấp số cộng, xác định đúng số số hạng và đơn vị.',1,[3,4],R`Ghép số hạng đầu với cuối, thứ hai với áp cuối. Mỗi cặp có tổng không đổi, suy ra $S_n=n(u_1+u_n)/2$.`, 'Nhầm số hạng cuối với số số hạng; bỏ chia hai.',(s,d)=>{
  const a=n(s),step=1+s%4,N=5+s%8,last=a+(N-1)*step,key=N*(a+last)/2;
  return numeric(d>=2?`Một khán đài có ${N} hàng, hàng đầu ${a} ghế, mỗi hàng sau thêm ${step} ghế. Có tổng cộng bao nhiêu ghế?`:`Tính tổng ${N} số hạng đầu cấp số cộng có ${math(`u_1=${a}`)}, ${math(`d=${step}`)}.`,key,R`$u_{${N}}=${last}$; $S_{${N}}=${N}(${a}+${last})/2=${key}$.`,hints('Cần tổng, không chỉ số ghế hàng cuối.','Ghép các số hạng cách đều hai đầu.','Tìm số hạng cuối trước.','Ví dụ khác: tổng $1+2+3+4$ có thể ghép $1+4$ và $2+3$.'),Array.from({length:N},(_,i)=>a+i*step).reduce((a,b)=>a+b,0));
 }),
 geometric:concept('Số hạng cấp số nhân','Nhận biết cấp số nhân, xác định công bội và số hạng tổng quát.',1,[3,4],R`Từ số hạng đầu tới số hạng thứ n cần $n-1$ phép nhân. Chốt $u_n=u_1q^{n-1}$; với công bội âm phải xét tính chẵn/lẻ của số mũ.`, 'Dùng n phép nhân; bỏ dấu công bội âm.',(s,d)=>{
  const a=n(s),q=d>=2?-2:2,N=3+s%5,key=a*q**(N-1);
  let verify=a;for(let i=1;i<N;i++)verify*=q;
  return numeric(`Cấp số nhân có ${math(`u_1=${a}`)}, ${math(`q=${q}`)}. Tính ${math(`u_{${N}}`)}.`,key,R`$u_{${N}}=${a}\cdot(${q})^{${N-1}}=${key}$.`,hints('Xác định số lần nhân từ vị trí đầu.','Dùng lũy thừa của công bội.','Kiểm dấu của công bội và số mũ.','Ví dụ khác: hai lần nhân số âm cho kết quả dương.'),verify);
 }),
 geometricSum:concept('Tổng cấp số nhân','Tính tổng hữu hạn cấp số nhân và mô hình hóa tăng trưởng theo tỉ lệ.',1,[3,4],R`Viết $S$ và $qS$ theo cột để triệt tiêu số hạng, suy ra $S_n=u_1(1-q^n)/(1-q)$ khi $q\ne1$. Phân biệt lượng ở thời điểm cuối với tổng qua các thời điểm.`, 'Tính số hạng cuối thay tổng; áp dụng mẫu bằng không khi q bằng một.',(s)=>{
  const a=n(s),q=2,N=3+s%5,key=a*(q**N-1)/(q-1);
  return numeric(`Một trò chơi thưởng vòng đầu ${a} xu; mỗi vòng sau thưởng gấp đôi vòng trước. Sau ${N} vòng, tổng xu thưởng bằng bao nhiêu?`,key,R`Các khoản thưởng là cấp số nhân $u_1=${a}$, $q=2$. $S_{${N}}=${a}(2^{${N}}-1)=${key}$.`,hints('Liệt kê khoản thưởng từng vòng để xác định cần tổng.','Mỗi khoản tăng theo cùng một tỉ số.','Ghi số vòng là số số hạng.','Ví dụ khác: thưởng $1,2,4$ qua ba vòng có tổng $7$.'),Array.from({length:N},(_,i)=>a*2**i).reduce((a,b)=>a+b,0));
 }),
};

Object.assign(bank,{
 spatialAxioms:concept('Điểm, đường thẳng, mặt phẳng','Sử dụng các tính chất thừa nhận về điểm, đường thẳng và mặt phẳng; nhận ra điều kiện xác định duy nhất.',1,[5],R`Dùng ba que và tấm bìa: hai điểm phân biệt xác định đường thẳng, ba điểm không thẳng hàng xác định mặt phẳng. Nếu hai điểm của một đường nằm trong mặt phẳng thì cả đường nằm trong mặt phẳng. Nhấn mạnh điều kiện không thẳng hàng.`, 'Bỏ điều kiện không thẳng hàng; suy ba điểm bất kỳ xác định duy nhất mặt phẳng.',(s)=>{
  const count=4+s%9;
  return open(`Có ${count} điểm phân biệt cùng nằm trên đường thẳng ${math('d')}. Một học sinh cho rằng chúng xác định duy nhất một mặt phẳng. Kết luận đúng không? Nếu thêm điểm ${math('A\\notin d')}, hãy xác định mặt phẳng chứa tất cả các điểm.`,R`Kết luận ban đầu sai: có nhiều mặt phẳng qua $d$. Khi thêm $A\notin d$, chọn hai điểm phân biệt $B,C$ trên $d$; ba điểm $A,B,C$ không thẳng hàng xác định duy nhất $(ABC)$, chứa cả $d$.`,hints('Xem các điểm có thẳng hàng hay không.','Đối chiếu điều kiện xác định một mặt phẳng.','Chọn hai điểm trên đường đã cho và xét điểm thêm vào.','Ví dụ khác: nhiều tờ giấy có thể xoay quanh cùng một cạnh.'),['Nêu được vì sao không duy nhất khi tất cả điểm thẳng hàng.','Dùng ba điểm không thẳng hàng hoặc đường và điểm ngoài đường.']);
 }),
 planeIntersection:concept('Xác định mặt phẳng và giao tuyến','Tìm hai điểm chung phân biệt để xác định giao tuyến hai mặt phẳng.',1,[5],R`Vẽ hình chóp bằng nét thấy/nét khuất. Muốn tìm giao tuyến, đánh dấu hai điểm cùng thuộc cả hai mặt phẳng; không lấy giao điểm trên hình vẽ nếu chưa chứng minh đồng phẳng.`, 'Nhận giao điểm của hai nét trên giấy thành giao điểm không gian.',(s)=>{
  const a=n(s);
  return open(`Cho hình chóp ${math('S.ABCD')} có đáy hình bình hành, ${math(`AB=${a}`)}, ${math(`AD=${a+2}`)}. Hai đường chéo đáy cắt tại ${math('O')}. Xác định giao tuyến ${math('(SAC)\\cap(SBD)')}; giải thích hai điểm chung.`,R`$S$ thuộc cả hai mặt phẳng. $O\in AC$ và $O\in BD$ nên $O$ cũng chung. Vì $S\ne O$, giao tuyến là $SO$; các độ dài đáy không làm thay đổi lập luận.`,hints('Tìm một điểm chung đã có trong tên hai mặt phẳng.','Điểm chung thứ hai có thể nằm trong đáy.','Xét giao điểm hai đường chéo đáy.','Ví dụ khác: hai mặt phẳng phân biệt chứa cùng hai điểm thì chứa đường nối hai điểm đó.'),['Nêu hai điểm chung và chứng minh từng điểm thuộc cả hai mặt phẳng.','Kết luận giao tuyến đúng, không dùng hình chiếu làm chứng minh.']);
 }),
 tetrahedron:concept('Hình chóp, tứ diện và giao điểm','Nhận dạng hình chóp/tứ diện; tìm giao điểm đường thẳng với mặt phẳng bằng đường phụ đồng phẳng.',1,[5],R`Chỉ đỉnh, đáy, cạnh bên, mặt bên trên mô hình. Tìm giao điểm một đường với mặt phẳng bằng cách đặt đường trong mặt phẳng phụ rồi tìm giao tuyến hai mặt phẳng.`, 'Gọi đoạn chéo bất kỳ là cạnh; tìm giao điểm chỉ bằng nhìn nét vẽ.',(s)=>{
  const k=n(s);
  return open(`Cho tứ diện ${math('SABC')}, điểm ${math('M\\in AB')} thỏa ${math(`AM:MB=1:${k}`)}, ${math('N\\in AC')} thỏa ${math(`AN:NC=1:${k+1}`)}. Gọi ${math('I=MN\\cap BC')}. Xác định giao điểm ${math('MN\\cap(SBC)')}; giải thích vì sao ${math('I')} tồn tại.`,R`$MN$ và $BC$ cùng thuộc $(ABC)$. Do $AM/AB=1/${k+1}\ne AN/AC=1/${k+2}$, hai đường không song song, nên có $I$. Vì $I\in BC\subset(SBC)$, giao điểm cần tìm là $I$.`,hints('Đưa hai đường cần xét về cùng mặt phẳng đáy.','So sánh hai tỉ lệ tính từ cùng đỉnh.','Phân biệt tỉ lệ đoạn nhỏ với tỉ lệ trên toàn cạnh.','Ví dụ khác: $AM:MB=1:2$ cho $AM/AB=1/3$.'),['Chứng minh hai đường trong đáy không song song.','Xác định giao điểm thuộc đường và mặt phẳng yêu cầu.']);
 }),
 linesPosition:concept('Vị trí hai đường thẳng trong không gian','Phân biệt cắt nhau, song song và chéo nhau qua điều kiện đồng phẳng.',1,[6],R`Dùng hai que: không cắt nhau chưa đủ để song song. Trong một mặt phẳng, hai đường phân biệt không cắt nhau mới song song. Hai cạnh đối của tứ diện là ví dụ chéo nhau.`, 'Cho rằng hai đường không gặp trên hình là song song.',(s)=>{
  const k=n(s);
  return open(`Trong tứ diện ${math('ABCD')}, ${math(`AB=${k}`)}, ${math(`CD=${k+1}`)}. Xét vị trí ${math('AB')} và ${math('CD')}. Nếu chúng cùng nằm trong một mặt phẳng thì mâu thuẫn với giả thiết nào?`,R`$AB$ và $CD$ chéo nhau. Nếu chúng đồng phẳng thì cả bốn đỉnh $A,B,C,D$ cùng nằm trong mặt phẳng, trái với tứ diện không suy biến. Chỉ so sánh độ dài không quyết định song song.`,hints('Xem hai cạnh có đỉnh chung hay không.','Thử giả sử hai đường cùng một mặt phẳng.','Suy ra vị trí của bốn đỉnh dưới giả sử đó.','Ví dụ khác: hai đường không cắt nhau trong hai mặt phẳng khác nhau chưa chắc song song.'));
 }),
 parallelLines:concept('Tính chất đường thẳng song song','Chứng minh hai đường thẳng song song bằng đường trung bình hoặc song song cùng đường thứ ba.',1,[6],R`Chốt tính duy nhất của đường qua một điểm song song với đường đã cho. Đặt các cặp đường cần xét vào một tam giác hoặc một mặt phẳng đã biết.`, 'Dùng định lý đường trung bình khi chưa chứng minh điểm là trung điểm.',(s)=>{
  const k=n(s);
  return open(`Cho tứ diện ${math('SABC')}; ${math('M,N,P')} lần lượt là trung điểm ${math('SA,SB,SC')}, ${math(`AB=${2*k}`)}, ${math(`BC=${2*k+2}`)}. Chứng minh ${math('MN\\parallel AB')}, ${math('NP\\parallel BC')}; tính ${math('MN+NP')}.`,R`Trong tam giác $SAB$, $MN$ là đường trung bình nên $MN\parallel AB$, $MN=${k}$. Trong tam giác $SBC$, $NP\parallel BC$, $NP=${k+1}$. Tổng bằng $${2*k+1}$.`,hints('Mỗi cặp trung điểm nằm trong một tam giác riêng.','Dùng định lý đường trung bình trong mặt phẳng của tam giác.','Viết tên tam giác trước khi kết luận song song.','Ví dụ khác: đường nối trung điểm hai cạnh tam giác dài bằng nửa cạnh còn lại.'));
 }),
 linePlane:concept('Đường thẳng song song mặt phẳng','Dùng định nghĩa và điều kiện để chứng minh đường thẳng song song mặt phẳng, tránh trường hợp nằm trong mặt phẳng.',1,[7],R`Nêu ba khả năng: đường nằm trong, cắt, hoặc không có điểm chung với mặt phẳng. Muốn chứng minh song song, tìm một đường trong mặt phẳng song song đường cần xét và kiểm đường cần xét không thuộc mặt phẳng.`, 'Bỏ điều kiện đường không nằm trong mặt phẳng.',(s)=>{
  const k=n(s);
  return open(`Cho tứ diện ${math('SABC')}; ${math('M\\in SA, N\\in SB')} thỏa ${math(`SM/SA=SN/SB=1/${k+1}`)}. Chứng minh ${math('MN\\parallel(ABC)')}. Có thể chỉ ghi ${math('MN\\parallel AB')} rồi kết luận mà không xét vị trí ${math('MN')} không?`,R`Trong tam giác $SAB$, hai tỉ lệ bằng nhau nên $MN\parallel AB$. Vì $M$ nằm trong cạnh $SA$ và khác $A$, $M\notin(ABC)$; do đó $MN$ không nằm trong $(ABC)$. Lại có $AB\subset(ABC)$, suy ra $MN\parallel(ABC)$. Cần điều kiện không thuộc mặt phẳng.`,hints('Tìm một đường thuộc mặt phẳng đích.','Dùng hai tỉ lệ cùng tính từ đỉnh S.','Kiểm một điểm của đường cần xét có nằm ở đáy không.','Ví dụ khác: một cạnh đáy song song với đường trong đáy chưa làm cạnh đó song song với cả mặt phẳng đáy theo định nghĩa không giao.'));
 }),
 linePlaneProperty:concept('Giao tuyến và song song','Vận dụng tính chất giao tuyến khi một mặt phẳng chứa đường song song mặt phẳng khác.',1,[7],R`Vẽ mặt phẳng phụ chứa đường $a$. Nếu $a\parallel(P)$ và mặt phẳng phụ cắt $(P)$ theo $b$ thì $a\parallel b$. Phân biệt giả thiết đường song song mặt phẳng với đường nằm trong mặt phẳng.`, 'Kết luận mọi đường của mặt phẳng đều song song đường ban đầu.',(s)=>{
  const k=n(s);
  return open(`Cho hình chóp ${math('S.ABCD')} có đáy hình thang ${math('AB\\parallel CD')}, ${math(`AB=${k+3}`)}, ${math(`CD=${k}`)}. Xác định giao tuyến của ${math('(SAB)')} và ${math('(SCD)')}; trình bày lập luận.`,R`Hai mặt phẳng cùng chứa $S$, lần lượt chứa hai đường song song $AB,CD$. Giao tuyến là đường thẳng qua $S$ song song $AB$ và $CD$. Không phải một cạnh bên chỉ vì cạnh ấy đi qua $S$.`,hints('Ghi điểm chung của hai mặt phẳng.','Tìm hai đường song song, mỗi đường nằm trong một mặt phẳng.','Định hướng đường qua điểm chung.','Ví dụ khác: giao tuyến qua điểm chung và song song hai giao tuyến song song đã biết.'));
 }),
 planesParallel:concept('Hai mặt phẳng song song','Chứng minh hai mặt phẳng song song bằng hai đường cắt nhau; không dùng chỉ một cặp đường.',2,[3],R`Dựng hai đường cắt nhau trong mặt phẳng thứ nhất, lần lượt song song hai đường cắt nhau trong mặt phẳng thứ hai. Một cặp đường song song chưa đủ quyết định hai mặt phẳng.`, 'Chứng minh một đường song song rồi kết luận hai mặt phẳng song song.',(s)=>{
  const k=n(s);
  return open(`Trong tứ diện ${math('SABC')}, ${math('M,N,P')} lần lượt thuộc ${math('SA,SB,SC')} và ${math(`SM/SA=SN/SB=SP/SC=1/${k+1}`)}. Chứng minh ${math('(MNP)\\parallel(ABC)')}.`,R`Từ tỉ lệ trong các tam giác $SAB,SAC$ suy ra $MN\parallel AB$, $MP\parallel AC$. Hai đường $MN,MP$ cắt nhau tại $M$; hai đường $AB,AC$ cắt nhau tại $A$. Do vậy $(MNP)\parallel(ABC)$.`,hints('Cần hai hướng khác nhau trong mỗi mặt phẳng.','Xét hai tam giác có chung một cạnh bên.','Chứng minh từng cặp đường song song trước.','Ví dụ khác: hai đường cắt nhau tạo hai hướng đủ để xác định mặt phẳng.'),['Nêu đủ hai cặp đường song song.','Chỉ rõ điều kiện cắt nhau và kết luận hai mặt phẳng.']);
 }),
 thales:concept('Định lý Thales trong không gian','Dùng ba mặt phẳng song song để lập tỉ lệ đoạn thẳng trên hai cát tuyến.',2,[3],R`Ba tấm bìa song song cắt hai que theo các bộ điểm tương ứng. Đặt tỉ lệ các đoạn theo cùng thứ tự, không trộn đoạn đơn với đoạn toàn phần.`, 'Ghép sai thứ tự điểm hoặc dùng AB/BC thành AB/AC.',(s)=>{
  const a=n(s),b=a+1,c=2*a,key=2*b;
  return numeric(`Ba mặt phẳng song song cắt hai cát tuyến lần lượt tại ${math('A,B,C')} và ${math("A',B',C'")} theo cùng thứ tự. Biết ${math(`AB=${a},\\ BC=${b},\\ A'B'=${c}`)}. Tính ${math("B'C'")}.`,key,R`$AB/BC=A'B'/B'C'$, nên $B'C'=${c}\cdot${b}/${a}=${key}$.`,hints('Ghép các đoạn nằm giữa cùng hai mặt phẳng.','Dùng tỉ số bằng nhau trên hai cát tuyến.','Viết phân số theo cùng thứ tự điểm.','Ví dụ khác: nếu một cát tuyến có các đoạn gấp ba cát tuyến kia thì mọi đoạn tương ứng cùng hệ số.'),b*(c/a));
 }),
 prism:concept('Lăng trụ và hình hộp','Nhận dạng các mặt song song, cạnh song song và quan hệ trung điểm trong hình lăng trụ/hình hộp.',2,[3],R`Dùng hình hộp để chỉ hai mặt đáy song song và các mặt bên hình bình hành. Các cạnh bên song song, bằng nhau; không tự kết luận vuông góc khi chưa cho lăng trụ đứng.`, 'Ngầm coi mọi lăng trụ là lăng trụ đứng.',(s)=>{
  const k=n(s);
  return open(`Cho lăng trụ ${math("ABC.A'B'C'")} có ${math(`AB=${k}`)}, ${math(`BC=${k+1}`)}, ${math(`AA'=${k+2}`)}. Nêu hai cặp mặt/cạnh song song và xác định ${math("A'B'")}, ${math("BB'")}. Có suy ra ${math("AA'\\perp(ABC)")} không?`,R`$(ABC)\parallel(A'B'C')$; $AA'\parallel BB'\parallel CC'$ và $AB\parallel A'B'$. $A'B'=${k}$, $BB'=${k+2}$. Không suy ra vuông góc nếu chưa có giả thiết lăng trụ đứng.`,hints('Tách tính chất mọi lăng trụ với tính chất lăng trụ đứng.','Mặt bên là hình bình hành.','So sánh các cạnh đối trong mặt bên.','Ví dụ khác: hình bình hành xiên không bắt buộc có góc vuông.'));
 }),
 projection:concept('Phép chiếu song song','Vận dụng các tính chất được bảo toàn bởi phép chiếu song song và vẽ hình biểu diễn đúng.',2,[3],R`Chiếu một tam giác giấy theo các tia cùng phương. Phép chiếu bảo toàn thẳng hàng, song song (hoặc ảnh trùng nhau), tỉ số đoạn cùng đường; không bảo toàn độ dài/góc nói chung.`, 'Đo góc/độ dài trên hình biểu diễn để kết luận hình thật.',(s)=>{
  const k=n(s);
  return open(`Trên đoạn ${math('AB')}, điểm ${math('M')} thỏa ${math(`AM:MB=1:${k}`)}. Phép chiếu song song cho ảnh ${math("A',M',B'")} phân biệt. Biết ${math(`A'B'=${3*(k+1)}`)} cm. Tính ${math("A'M'")}; giải thích có suy ra ${math(`AB=${3*(k+1)}`)} cm không.`,R`Tỉ số được bảo toàn: $A'M':M'B'=1:${k}$. Suy ra $A'M'=3$ cm. Không thể suy độ dài thật $AB$ từ độ dài ảnh vì phép chiếu không bảo toàn độ dài nói chung.`,hints('Điểm ảnh vẫn nằm theo cùng tỉ lệ trên đường ảnh.','Chuyển tỉ lệ hai phần thành tỉ lệ trên toàn đoạn.','Tổng số phần bằng tổng hai số trong tỉ lệ.','Ví dụ khác: trung điểm có ảnh là trung điểm khi ảnh đoạn không suy biến.'));
 }),
 grouped:concept('Ghép nhóm mẫu số liệu','Ghép đúng dữ liệu vào khoảng nửa kín, xác định tần số, cỡ mẫu và giá trị đại diện.',2,[1],R`Chọn các khoảng không chồng lấn; đầu trái nhận, đầu phải chuyển nhóm kế. Tần số đếm số dữ liệu, giá trị đại diện là trung điểm khoảng; ghép nhóm làm mất giá trị từng quan sát.`, 'Đếm điểm biên vào hai nhóm; nhầm tần số với giá trị đại diện.',(s)=>{
  const a=10+n(s),data=[a,a+1,a+2,a+3,a+4,a+5,a+6,a+8,a+9,a+10];
  return open(`Ghép mẫu ${math(data.join(';'))} vào hai nhóm ${math(`[${a};${a+5})`)} và ${math(`[${a+5};${a+11})`)}. Cho tần số từng nhóm, cỡ mẫu, giá trị đại diện; chỉ ra nhóm chứa giá trị ${math(`${a+5}`)}.`,R`Tần số hai nhóm đều $5$, cỡ mẫu $10$. Giá trị đại diện lần lượt $${a+2.5}$ và $${a+8}$. Điểm biên $${a+5}$ thuộc nhóm thứ hai.`,hints('Đọc dấu ngoặc của mỗi khoảng.','Đếm từng dữ liệu đúng một lần.','Kiểm tổng các tần số bằng cỡ mẫu.','Ví dụ khác: giá trị ở đầu phải của khoảng $[2;4)$ không thuộc khoảng đó.'));
 }),
 groupedMean:concept('Số trung bình ghép nhóm','Tính trung bình mẫu ghép nhóm bằng giá trị đại diện và tần số; giải thích tính xấp xỉ.',2,[1],R`Thay mỗi nhóm bằng trung điểm; lập cột giá trị đại diện nhân tần số. Tổng chia cỡ mẫu. Đây là ước lượng từ dữ liệu ghép nhóm, không mặc nhiên là trung bình chính xác mẫu ban đầu.`, 'Lấy trung bình các trung điểm mà không nhân tần số.',(s)=>{
  const a=n(s),f1=2+s%4,f2=4+s%5,m1=a+2,m2=a+6,key=(m1*f1+m2*f2)/(f1+f2);
  return numeric(`Hai nhóm ${math(`[${a};${a+4})`)}, ${math(`[${a+4};${a+8})`)} có tần số lần lượt ${f1}, ${f2}. Tính số trung bình mẫu ghép nhóm.`,key,R`Trung điểm $${m1},${m2}$; $\bar x=(${m1}\cdot${f1}+${m2}\cdot${f2})/${f1+f2}=${frac(m1*f1+m2*f2,f1+f2)}$.`,hints('Tìm giá trị đại diện từng nhóm.','Mỗi nhóm đóng góp theo số quan sát của nhóm.','Lập tổng tích trung điểm với tần số.','Ví dụ khác: nhóm có tần số gấp đôi cần được tính trọng số gấp đôi.'),[...Array(f1).fill(m1),...Array(f2).fill(m2)].reduce((x,y)=>x+y,0)/(f1+f2));
 }),
 groupedMedian:concept('Trung vị ghép nhóm','Xác định nhóm chứa trung vị và nội suy từ tần số tích lũy.',2,[1],R`Tính tần số tích lũy, tìm nhóm chứa vị trí $n/2$. Nội suy trong nhóm bằng độ rộng; không lấy trung điểm nhóm làm trung vị trong mọi trường hợp.`, 'Dùng tần số nhóm thay tần số tích lũy trước nhóm.',(s)=>{
  const a=n(s),freq=[4,8,4],key=a+6;
  return numeric(`Mẫu ghép nhóm có các khoảng ${math(`[${a};${a+4})`)}, ${math(`[${a+4};${a+8})`)}, ${math(`[${a+8};${a+12})`)} với tần số ${math(freq.join(';'))}. Tính trung vị theo công thức nội suy.`,key,R`$n=16$, vị trí $n/2=8$ thuộc nhóm giữa; $M_e=${a+4}+((8-4)/8)\cdot4=${key}$.`,hints('Tính tổng tần số trước.','Tìm nhóm mà tần số tích lũy đi qua vị trí giữa.','Lấy vị trí giữa trừ số quan sát trước nhóm.','Ví dụ khác: nếu vị trí giữa ở chính giữa lượng quan sát của một nhóm thì điểm nội suy ở trung điểm nhóm.'),a+4+4/8*4);
 }),
 quartiles:concept('Tứ phân vị ghép nhóm','Xác định nhóm chứa tứ phân vị và nội suy đúng vị trí.',2,[1],R`Đánh dấu vị trí $n/4$, $n/2$, $3n/4$ trên tần số tích lũy; dùng cận trái, tần số trước nhóm, tần số nhóm và độ rộng.`, 'Chọn nhóm từ số thứ tự nhóm thay vì tần số tích lũy.',(s,d)=>{
  const a=n(s),ask=d%2?3:1,key=a+(ask===1?2:6);
  return numeric(`Bốn nhóm có cùng tần số ${math('4')}: ${math(`[${a};${a+2}),[${a+2};${a+4}),[${a+4};${a+6}),[${a+6};${a+8})`)}. Tính ${math(`Q_${ask}`)} bằng nội suy.`,key,R`$n=16$, vị trí $${ask===1?'n/4=4':'3n/4=12'}$ rơi đúng ranh giới nhóm, nên $Q_${ask}=${key}$. Hai cách lấy nhóm kề cho cùng ranh giới.`,hints('Tìm vị trí phần tư trên toàn mẫu.','Cộng tần số lần lượt để tìm ranh giới.','Mỗi nhóm đang chứa cùng số quan sát.','Ví dụ khác: tại ranh giới nhóm, nội suy có thể cho đúng cận phải nhóm trước.'),a+ask*2);
 }),
 mode:concept('Mốt ghép nhóm','Nhận biết nhóm mốt và áp dụng công thức nội suy mốt khi các nhóm có cùng độ rộng.',2,[1],R`Chọn nhóm có tần số lớn nhất; dùng chênh lệch với nhóm liền trước và liền sau. Khi hai chênh lệch bằng nhau, mốt nằm giữa nhóm.`, 'Lấy cận trái nhóm mốt làm mốt; bỏ điều kiện các nhóm đều độ rộng.',(s)=>{
  const a=n(s),f=2+s%5,key=a+6;
  return numeric(`Ba nhóm ${math(`[${a};${a+4}),[${a+4};${a+8}),[${a+8};${a+12})`)} có tần số ${math(`${f};${f+6};${f}`)}. Tính mốt mẫu ghép nhóm.`,key,R`Nhóm giữa là nhóm mốt. $M_o=${a+4}+\frac{6}{6+6}\cdot4=${key}$.`,hints('So sánh tần số để chọn nhóm mốt.','Tính hai chênh lệch với nhóm kề.','Dùng chênh lệch phía trước chia tổng hai chênh lệch.','Ví dụ khác: biểu đồ tần số đối xứng quanh nhóm cao nhất cho mốt ở giữa nhóm.'),a+4+(f+6-f)/(2*(f+6)-f-f)*4);
 }),
 limitSequence:concept('Giới hạn hữu hạn của dãy','Tính giới hạn dãy hữu tỉ bằng chia cho lũy thừa lớn nhất và giải thích phần tiến về không.',2,[2],R`Với $n$ tăng, $1/n$ và $1/n^2$ tiến về không. Chia tử/mẫu cho cùng lũy thừa cao nhất, không thay ký hiệu vô cực như một số.`, 'Coi vô cực chia vô cực bằng một; chỉ so hệ số mà bỏ bậc.',(s)=>{
  const a=n(s),b=a+2,c=2+s%5;
  return numeric(`Tính ${math(`\\lim_{n\\to\\infty}\\frac{${a}n+${b}}{${c}n+1}`)}.`,a/c,R`Chia tử/mẫu cho $n$: $(${a}+${b}/n)/(${c}+1/n)\to${frac(a,c)}$.`,hints('Tìm bậc cao nhất của n ở tử và mẫu.','Chia cả tử và mẫu cho cùng biểu thức.','Theo dõi các phần chứa nghịch đảo của n.','Ví dụ khác: $1/n$ nhỏ dần về không khi n tăng.'),((a*1e12+b)/(c*1e12+1)));
 }),
 infiniteSeries:concept('Tổng cấp số nhân lùi vô hạn','Kiểm tra điều kiện công bội rồi tính tổng cấp số nhân lùi vô hạn.',2,[2],R`Từ tổng hữu hạn, cho $n$ tăng và dùng $q^n\to0$ khi $|q|<1$. Chốt $S=u_1/(1-q)$; nếu $|q|\ge1$ không dùng công thức này.`, 'Áp dụng công thức tổng vô hạn cho mọi công bội.',(s,d)=>{
  const a=n(s),q=d%2?-0.5:0.5,key=a/(1-q);let verify=0;for(let i=0;i<60;i++)verify+=a*q**i;
  return numeric(`Tính tổng vô hạn ${math(`${a}+${a*q}+${a*q*q}+\\cdots`)}; các số hạng lập cấp số nhân.`,key,R`$q=${q}$, $|q|<1$; $S=${a}/(1-(${q}))=${frac(2*a,q>0?1:3)}$.`,hints('Lập tỉ số hai số hạng liên tiếp.','Kiểm trị tuyệt đối công bội trước khi tính tổng.','Phân biệt số hạng đầu với tổng.','Ví dụ khác: $1+1/2+1/4+\\cdots$ có các tổng riêng tiến dần tới một giá trị hữu hạn.'),verify);
 }),
 infinitySequence:concept('Giới hạn vô cực của dãy','Xác định dấu và độ lớn của số hạng chi phối để tìm giới hạn vô cực.',2,[2],R`Tách số hạng bậc cao nhất. Dãy ra vô cực nghĩa là vượt mọi ngưỡng về một phía; dãy đổi dấu không tự có giới hạn vô cực một phía.`, 'Kết luận mọi dãy không bị chặn có giới hạn dương vô cực.',(s,d)=>{
  const a=n(s),neg=d%2===1;
  return open(`Tìm ${math(`\\lim_{n\\to\\infty}(${neg?'-':''}${a}n^2+${a+1}n)`)}. Giải thích bằng số hạng chi phối; so sánh với dãy ${math('(-1)^nn')}.`,R`Số hạng bậc hai chi phối, nên giới hạn là $${neg?'-':'+'}\infty$. Dãy $(-1)^nn$ có các dãy con chẵn và lẻ đi về hai phía, nên không có giới hạn một phía $+\infty$ hoặc $-\infty$.`,hints('So tốc độ tăng của các lũy thừa.','Tách lũy thừa lớn nhất ra ngoài.','Xét dấu hệ số dẫn đầu.','Ví dụ khác: hai dãy con có hành vi khác nhau có thể bác bỏ giới hạn chung.'));
 }),
 functionLimit:concept('Giới hạn hàm tại một điểm','Tính giới hạn hữu hạn bằng phân tích nhân tử; phân biệt giới hạn và giá trị tại điểm.',2,[2],R`Thay thử để nhận dạng, nhưng $0/0$ chưa là kết quả. Phân tích rồi rút gọn chỉ với $x$ khác điểm xét; giới hạn có thể tồn tại dù hàm chưa xác định tại điểm.`, 'Ghi 0/0 là đáp án; cho rằng không xác định tại điểm thì không có giới hạn.',(s)=>{
  const a=n(s),key=2*a;
  return numeric(`Tính ${math(`\\lim_{x\\to${a}}\\frac{x^2-${a*a}}{x-${a}}`)}.`,key,R`Với $x\ne${a}$, thương bằng $x+${a}$; giới hạn bằng $${2*a}$.`,hints('Thay trực tiếp đang cho dạng gì?','Nhận ra hiệu hai bình phương.','Rút gọn trên lân cận bỏ điểm đang xét.','Ví dụ khác: $(t^2-1)/(t-1)=t+1$ khi $t\\ne1$.'),((a+1e-3)+a+(a-1e-3)+a)/2);
 }),
 oneSided:concept('Giới hạn một bên','So sánh hai giới hạn một bên để quyết định giới hạn hai phía.',2,[2],R`Vẽ hai nhánh nối hoặc lệch nhau tại cùng hoành độ. Giới hạn hai phía tồn tại khi hai giới hạn một bên hữu hạn bằng nhau; giá trị tại điểm không quyết định hai giới hạn này.`, 'Chỉ tính bên phải rồi kết luận giới hạn hai phía.',(s)=>{
  const a=n(s),b=a+1;
  return open(`Cho ${math(`f(x)=\\begin{cases}x+${a},&x<1,\\\\${b}x+1,&x\\ge1.\\end{cases}`)} Tính giới hạn trái, phải tại ${math('1')}; kết luận giới hạn hai phía.`,R`Giới hạn trái $1+${a}=${a+1}$, phải $${b}+1=${a+2}$. Hai giá trị khác nhau nên giới hạn hai phía không tồn tại.`,hints('Dùng đúng biểu thức theo phía tiến tới.','Tính hai giá trị riêng trước khi so sánh.','Tiến từ trái nghĩa là dùng nhánh x nhỏ hơn điểm xét.','Ví dụ khác: một bước nhảy có thể có cả hai giới hạn một bên nhưng không có giới hạn chung.'));
 }),
 infinityFunction:concept('Giới hạn hàm tại vô cực','So sánh bậc tử/mẫu để tính giới hạn hàm hữu tỉ khi biến ra vô cực.',2,[2],R`Chia cho lũy thừa cao nhất ở mẫu. Phân biệt bậc tử thấp hơn, bằng hoặc cao hơn; không dùng quy tắc hệ số dẫn đầu khi bậc khác nhau.`, 'Chỉ lấy tỉ số hai hệ số dù tử mẫu khác bậc.',(s)=>{
  const a=n(s),b=2+s%5;
  return numeric(`Tính ${math(`\\lim_{x\\to+\\infty}\\frac{${a}x^2+3x+1}{${b}x^2+5}`)}.`,a/b,R`Chia tử/mẫu cho $x^2$; các phần $3/x,1/x^2,5/x^2$ về không, kết quả $${frac(a,b)}$.`,hints('Xác định bậc của tử và mẫu.','Dùng cùng một lũy thừa để chia.','Liệt kê các số hạng có giới hạn bằng không.','Ví dụ khác: $1/x^2$ tiến về không ở cả hai phía vô cực.'),(a*1e24+3e12+1)/(b*1e24+5));
 }),
 poleLimit:concept('Giới hạn vô cực tại điểm','Xét dấu để tìm giới hạn vô cực một bên và phân biệt mẫu bình phương.',2,[2],R`Lập bảng dấu quanh điểm làm mẫu bằng không. Tử dương chia mẫu dương rất nhỏ cho dương vô cực; đổi phía có thể đổi dấu nếu mẫu bậc lẻ.`, 'Bỏ dấu 0 phía trái/phải; coi mẫu bình phương đổi dấu.',(s)=>{
  const a=n(s),b=a+1;
  return open(`Tính các giới hạn ${math(`\\lim_{x\\to${a}^-}\\frac{${b}}{x-${a}}`)}, ${math(`\\lim_{x\\to${a}^+}\\frac{${b}}{x-${a}}`)} và ${math(`\\lim_{x\\to${a}}\\frac{${b}}{(x-${a})^2}`)}.`,R`Tử dương. Mẫu tuyến tính tiến về $0^-$ ở trái và $0^+$ ở phải, nên lần lượt $-\infty,+\infty$. Mẫu bình phương luôn dương ngoài điểm xét, nên giới hạn thứ ba $+\infty$.`,hints('Tách xét dấu với xét độ lớn.','Đánh dấu phía trái và phải của điểm.','Bình phương mẫu thay đổi điều gì về dấu?','Ví dụ khác: số dương chia số âm rất nhỏ cho số âm có độ lớn lớn.'));
 }),
 continuityPoint:concept('Liên tục tại điểm','Kiểm tra đủ giá trị tại điểm và giới hạn; tìm tham số làm hàm liên tục.',2,[2],R`Ba bước: hàm xác định tại điểm; giới hạn tồn tại; hai giá trị bằng nhau. Lỗ trên đồ thị được lấp đúng độ cao giới hạn mới tạo tính liên tục.`, 'Chỉ kiểm giá trị hàm hoặc chỉ kiểm giới hạn.',(s)=>{
  const a=n(s);
  return numeric(`Cho ${math(`f(x)=\\frac{x^2-${a*a}}{x-${a}}`)} khi ${math(`x\\ne${a}`)}, và ${math(`f(${a})=m`)}. Tìm ${math('m')} để hàm liên tục tại ${math(`${a}`)}.`,2*a,R`Giới hạn phần phân thức bằng $\lim_{x\to${a}}(x+${a})=${2*a}$. Liên tục đòi $m$ bằng giới hạn này.`,hints('Phân biệt công thức ngoài điểm với giá trị được gán tại điểm.','Tìm giới hạn trước, rồi dùng điều kiện liên tục.','Phân tích hiệu hai bình phương.','Ví dụ khác: lấp lỗ đồ thị phải đặt điểm đúng độ cao đường cong tiến tới.'),a+a);
 }),
 continuityInterval:concept('Liên tục trên khoảng','Xác định các khoảng liên tục của hàm hữu tỉ và căn thức theo miền xác định.',2,[2],R`Hàm đa thức liên tục trên toàn trục; hàm hữu tỉ liên tục tại nơi mẫu khác không. Với căn, xét thêm điều kiện biểu thức dưới căn không âm. Khoảng liên tục không đi qua điểm bị loại.`, 'Nêu liên tục trên toàn trục dù mẫu có nghiệm.',(s)=>{
  const a=n(s),b=a+2;
  return open(`Xác định miền xác định và các khoảng liên tục của ${math(`f(x)=\\frac{x+${b}}{x-${a}}`)}. Giải thích có thể nói liên tục trên ${math(`(${a-1};${a+1})`)} không.`,R`Miền xác định $\mathbb R\setminus\{${a}\}$. Hàm liên tục trên $(-\infty;${a})$ và $(${a};+\infty)$. Không liên tục trên khoảng chứa $${a}$ vì không xác định tại đó.`,hints('Tìm điểm làm mẫu bằng không.','Các khoảng phải nằm hoàn toàn trong miền xác định.','Chia trục số tại điểm bị loại.','Ví dụ khác: một khoảng không thể chứa lỗ của miền xác định nếu muốn xét liên tục trên cả khoảng.'));
 }),
 integerPower:concept('Lũy thừa nguyên và căn','Tính lũy thừa số mũ nguyên, căn bậc n; giữ điều kiện cơ số và dấu.',2,[4],R`Với cơ số khác không, $a^{-m}=1/a^m$. Căn bậc chẵn lấy giá trị không âm; $\sqrt{a^2}=|a|$. Căn bậc lẻ giữ được dấu số âm.`, 'Cho số mũ âm tạo kết quả âm; bỏ trị tuyệt đối khi lấy căn bình phương.',(s,d)=>{
  const a=n(s),degree=s%2?3:5;
  assert.equal((-a)**degree,-(a**degree));assert.equal(Math.round(Math.pow(a**4,1/4)),a);numericChecks+=2;
  return open(R`Tính $${a}^{-2}$, $\sqrt[${degree}]{-${a**degree}}$, $\sqrt[4]{${a**4}}$. ${d===0?'Giải thích vì sao hai căn vừa tính có dấu khác nhau.':R`Với số nguyên $n\ge2$, nêu điều kiện để $\sqrt[n]{t}$ có nghĩa trong số thực khi n chẵn và khi n lẻ; viết $\sqrt[n]{t^n}$ theo t.`}`,
    R`Ba kết quả là $1/${a*a}$, $-${a}$ và $${a}$. Căn bậc lẻ của số âm là số âm; căn bậc chẵn số học không âm. Khi n chẵn, cần $t\ge0$ cho $\sqrt[n]{t}$; khi n lẻ, t có thể là mọi số thực. Với mọi t thực, $\sqrt[n]{t^n}=|t|$ nếu n chẵn và bằng t nếu n lẻ.`,
    hints('Tách số mũ âm khỏi dấu của cơ số dưới căn.','Căn bậc chẵn chọn giá trị không âm; căn bậc lẻ giữ dấu.','Thử nâng kết quả dự kiến lên đúng bậc để đối chiếu.',R`Ví dụ khác: $\sqrt[3]{-${(a+1)**3}}=-${a+1}$, nhưng $\sqrt[4]{${(a+1)**4}}=${a+1}$.`),['Tính đúng nghịch đảo và cả hai căn khác bậc.','Giải thích đúng dấu; nêu đúng miền và quy tắc theo tính chẵn/lẻ khi được hỏi.']);
 }),
 realPower:concept('Lũy thừa hữu tỉ và thực','Đổi lũy thừa hữu tỉ sang căn; dùng quy tắc với số mũ vô tỉ và giải thích cách xấp xỉ lũy thừa thực khi cơ số dương.',2,[4],R`Với $a>0$, $a^{m/n}=\sqrt[n]{a^m}$. Với số vô tỉ alpha, chọn các số hữu tỉ r tiến gần alpha; lũy thừa a mũ alpha được xác định bằng giới hạn của a mũ r. Ví dụ các số 1,4; 1,41; 1,414 tiến gần căn hai. Các quy tắc cộng/nhân số mũ vẫn áp dụng cho số mũ thực khi a dương; không thay số vô tỉ bằng số thập phân hữu hạn rồi coi là chính xác.`, 'Cộng cơ số; đổi mũ hữu tỉ thành phép chia; coi xấp xỉ hữu hạn là giá trị chính xác của số mũ vô tỉ.',(s,d)=>{
  const a=n(s),power=d%2?3:2,den=d%2?2:3,baseValue=a**den,key=a**power;
  assert.ok(Math.abs(Math.pow(baseValue,power/den)-key)<1e-8);assert.ok(Math.abs(a**Math.SQRT2*a**(2-Math.SQRT2)-a*a)<1e-8);numericChecks+=2;
  return open(R`Tính chính xác $${baseValue}^{${power}/${den}}$ và $P=${a}^{\sqrt2}\cdot${a}^{2-\sqrt2}$. ${d===0?'Nêu quy tắc đã dùng.':R`Nếu $r_j\in\mathbb Q$ và $r_j\to\sqrt2$, giới hạn của $${a}^{r_j}$ biểu diễn lũy thừa thực nào? Vì sao không thay căn hai bằng 1,414 rồi gọi là kết quả chính xác?`}`,
    R`$${baseValue}=${a}^{${den}}$ nên lũy thừa hữu tỉ bằng $${a}^{${power}}=${key}$. Cơ số ${a} dương, cộng số mũ thực cho $P=${a}^{\sqrt2+2-\sqrt2}=${a}^2=${a*a}$. Theo định nghĩa lũy thừa với số mũ vô tỉ, $\lim_{j\to\infty}${a}^{r_j}=${a}^{\sqrt2}$. Số 1,414 chỉ xấp xỉ căn hai nên lũy thừa tương ứng chỉ là xấp xỉ.`,
    hints('Viết cơ số đầu dưới dạng lũy thừa nguyên; kiểm cơ số tích dương.','Quy tắc nhân cùng cơ số vẫn dùng cho số mũ thực.','Cộng toàn bộ hai số mũ của P trước khi tính giá trị.',R`Ví dụ khác: $b^{\pi}b^{1-\pi}=b$ khi b dương, dù pi không hữu tỉ.`),['Tính đúng lũy thừa hữu tỉ và tích có số mũ vô tỉ.', 'Nêu đúng quy tắc, cơ số dương; phân biệt giới hạn chính xác với xấp xỉ khi được hỏi.']);
 }),
 logarithm:concept('Khái niệm và quy tắc lôgarit','Đổi giữa dạng lũy thừa và lôgarit; dùng quy tắc tích, thương, lũy thừa đúng điều kiện.',2,[],R`Từ $a^b=c$ suy ra $\log_a c=b$ với $a>0,a\ne1,c>0$. Chốt quy tắc tích/thương; lôgarit của tổng không tách thành tổng các lôgarit.`, 'Tách lôgarit một tổng; bỏ điều kiện biểu thức trong log dương.',(s,d)=>{
  const a=2+s%4,k=2+s%5,m=1+s%3;
  return numeric(`Tính ${math(`\\log_${a}(${a**k})${d%2?'-':'+'}\\log_${a}(${a**m})`)}.`,k+(d%2?-m:m),R`Theo định nghĩa, hai lôgarit lần lượt $${k}$ và $${m}$; kết quả $${k+(d%2?-m:m)}$. Có thể gộp thành lôgarit ${d%2?'thương':'tích'}.`,hints('Cơ số và đối số đều đã dương.','Viết mỗi đối số thành lũy thừa cùng cơ số.','Đọc số mũ bằng định nghĩa lôgarit.','Ví dụ khác: $\\log_b(b^t)=t$ khi cơ số hợp lệ.'),Math.log(a**k)/Math.log(a)+(d%2?-1:1)*Math.log(a**m)/Math.log(a));
 }),
 logBase:concept('Đổi cơ số, log và ln','Dùng công thức đổi cơ số, phân biệt lôgarit thập phân và tự nhiên.',2,[],R`Chốt $\log_a b=\log_c b/\log_c a$, mẫu không bằng không. Ký hiệu $\log$ là cơ số 10, $\ln$ là cơ số $e$. Đổi cơ số giúp dùng máy tính nhưng cần giữ giá trị chính xác khi có thể.`, 'Đảo tử/mẫu; coi ln là log cơ số mười.',(s)=>{
  const a=2+s%4,k=2+s%7;
  return numeric(`Tính ${math(`\\frac{\\ln(${a**k})}{\\ln ${a}}`)} bằng đổi cơ số, không làm tròn trung gian.`,k,R`Biểu thức bằng $\log_${a}(${a}^{${k}})=${k}$.`,hints('Nhận dạng tỉ số hai lôgarit cùng cơ số.','Mẫu cho biết cơ số muốn đổi sang.','Viết đối số thành lũy thừa của cơ số mới.','Ví dụ khác: tỉ số $\\ln b/\\ln a$ có cơ số mới là a.'),Math.log(a**k)/Math.log(a));
 }),
});

const challenge=(prompt,solution,hint)=>open(prompt,solution,[hint],['Lập luận rõ điều kiện, chọn cách biến đổi phù hợp và kết luận đúng.']);
const advanced={
 radian:s=>{const a=n(s);return challenge(R`Hai bánh xe quét cùng độ dài cung. Bánh thứ nhất bán kính $${a}$ cm quay $\pi/3$ rad; bánh thứ hai quay $\pi/6$ rad. Tìm bán kính bánh thứ hai và giải thích quan hệ giữa bán kính với góc quay.`,R`Cùng $l=r\alpha$, nên $r_2(\pi/6)=${a}(\pi/3)$, suy ra $r_2=${2*a}$ cm. Với cung không đổi, bán kính tỉ lệ nghịch góc quay.`, 'Viết hai biểu thức của cùng độ dài cung.');},
 trigValue:s=>{const a=2*n(s)+1,b=(a*a-1)/2,c=(a*a+1)/2;return challenge(R`Biết $\sin x=${b}/${c}$, chưa biết góc phần tư. Có thể xác định duy nhất $\tan x$ không? Nêu đầy đủ khả năng.`,R`$\cos x=\pm${a}/${c}$ nên $\tan x=\pm${b}/${a}$. Sin dương cho phép góc phần tư I hoặc II; thiếu dữ kiện để chọn một dấu.`, 'Tìm tất cả dấu có thể có của hoành độ.');},
 identity:s=>{const a=n(s);return challenge(R`Có góc $x$ thỏa đồng thời $\sin x=${a}/${a+1}$ và $\pi<x<3\pi/2$ không? Giải thích mà không dùng máy tính.`,R`Không. Khoảng đã cho thuộc góc phần tư III, ở đó sin âm, trái với phân số dương đã cho.`, 'Kiểm tính tương thích của dữ kiện trước khi tính.');},
 opposite:s=>{const a=n(s);return challenge(R`Rút gọn $P=\sin(-${a}x)+\cos(\pi/2-${a}x)$. Nêu vì sao kết quả đúng với mọi $x$.`,R`Hai số hạng lần lượt $-\sin(${a}x)$ và $\sin(${a}x)$; $P=0$ với mọi $x$ theo công thức góc liên quan.`, 'Biến đổi cả hai số hạng về cùng một hàm và góc.');},
 supplement:s=>{const a=n(s);return challenge(R`Rút gọn $P=\sin(\pi-${a}x)+\sin(\pi+${a}x)+\cos(\pi-${a}x)$.`,R`Hai số hạng sin triệt tiêu; $P=-\cos(${a}x)$.`, 'Theo dõi từng dấu trước khi cộng.');},
 addition:s=>{const a=n(s);return challenge(R`Rút gọn $P=\sin(${a}x+\pi/3)\cos(${a}x)-\cos(${a}x+\pi/3)\sin(${a}x)$.`,R`Công thức sin hiệu cho $P=\sin(( ${a}x+\pi/3)-${a}x)=\sin(\pi/3)=\sqrt3/2$.`, 'Nhận hai góc toàn phần thay vì khai triển mọi tích.');},
 double:s=>{const a=n(s);return challenge(R`Biết $\cos2x=${a}/${a+2}$. Tìm $\sin^2x$, $\cos^2x$ rồi kiểm tổng hai kết quả.`,R`$\sin^2x=1/${a+2}$, $\cos^2x=${a+1}/${a+2}$; tổng bằng $1$.`, 'Dùng cả hai công thức hạ bậc và một bước kiểm độc lập.');},
 productSum:s=>{const a=n(s);return challenge(R`Rút gọn $\dfrac{\sin(${a}x)+\sin(${a+2}x)}{\cos(${a}x)+\cos(${a+2}x)}$ trên miền mẫu khác không; nêu điều kiện sau biến đổi.`,R`Tử $2\sin(${a+1}x)\cos x$, mẫu $2\cos(${a+1}x)\cos x$. Kết quả $\tan(${a+1}x)$ với $\cos x\ne0$ và $\cos(${a+1}x)\ne0$.`, 'Biến đổi cả tử và mẫu; không làm mất điểm bị loại.');},
 trigDomain:s=>{const a=n(s);return challenge(R`Tìm tập xác định của $y=1/(1-\cos(${a}x))$. Vì sao không thể dùng toàn bộ tập xác định của cosin?`,R`Mẫu khác không đòi $\cos(${a}x)\ne1$, tức $x\ne2k\pi/${a}$, $k\in\mathbb Z$. Việc cos xác định chưa bảo đảm phân thức xác định.`, 'Bổ sung điều kiện của phép chia vào điều kiện của hàm bên trong.');},
 parity:s=>{const a=n(s);return challenge(R`Xét tính chẵn/lẻ của $f(x)=\sin(${a}x)+\cos(${a}x)$. Dùng giá trị tại $0$ và một cặp điểm đối nhau để kiểm kết luận.`,R`$f(0)=1$ nên không lẻ. Với $x=\pi/(2\cdot${a})$, hai giá trị tại $x,-x$ là $1,-1$ nên không chẵn. Hàm không chẵn cũng không lẻ.`, 'Tổng một hàm chẵn với một hàm lẻ cần được xét lại, không được gán một nhãn sẵn.');},
 sinCosGraph:s=>{const a=n(s);return challenge(R`Không giải phương trình tổng quát, dùng hai đồ thị để đếm riêng số nghiệm của $\sin(${a}x)=1/2$ và $\cos(${a}x)=1/2$ trên $[0;4\pi/${a})$. Nêu vì sao số nghiệm bằng nhau nhưng vị trí nghiệm khác nhau.`,R`Khoảng chứa hai chu kỳ. Đường ngang 1/2 cắt mỗi đồ thị tại hai điểm trong mỗi chu kỳ, nên mỗi phương trình có bốn nghiệm. Trong chu kỳ đầu, sin đạt 1/2 ở góc pi/6 và 5pi/6; cos đạt ở pi/3 và 5pi/3. Hai đồ thị lệch pha nên vị trí giao điểm khác nhau.`, 'Đếm giao điểm riêng trên từng đồ thị; không lấy nghiệm của sin làm nghiệm của cos.');},
 tanCotGraph:s=>{const a=n(s);return challenge(R`Bạn nói $\tan(${a}x)$ đồng biến trên toàn bộ tập xác định vì mỗi nhánh đều tăng. Phản biện bằng hai điểm nằm hai phía của $\pi/(2\cdot${a})$.`,R`Chọn $x_1=\pi/(4\cdot${a})$, $x_2=3\pi/(4\cdot${a})$: $x_1<x_2$ nhưng hai giá trị là $1,-1$. Hàm chỉ tăng trên từng khoảng liên tục, không trên toàn miền rời nhau.`, 'Hai điểm ở hai nhánh khác nhau có thể tạo phản ví dụ.');},
 sinEquation:s=>{const a=n(s);return challenge(R`Giải $\sin(${a}x+\pi/6)=1/2$ trên $[0;2\pi/${a})$.`,R`Góc bằng $\pi/6+2k\pi$ hoặc $5\pi/6+2k\pi$, nên $x=2k\pi/${a}$ hoặc $2\pi/(3\cdot${a})+2k\pi/${a}$. Trong khoảng: $0,2\pi/(3\cdot${a})$.`, 'Giải theo toàn bộ góc rồi lọc khoảng sau cùng.');},
 cosEquation:s=>{const a=n(s);return challenge(R`Giải $\cos(${a}x-\pi/3)=1$ trên $[0;2\pi/${a})$. Vì sao ở giá trị này chỉ cần một họ nghiệm?`,R`Góc bằng $2k\pi$, nên $x=\pi/(3\cdot${a})+2k\pi/${a}$. Khoảng cho một nghiệm $\pi/(3\cdot${a})$; hai họ đối xứng trùng nhau khi cos bằng một.`, 'Xem vị trí điểm có hoành độ lớn nhất trên đường tròn.');},
 tanEquation:s=>{const a=n(s);return challenge(R`Giải $\tan(${a}x-\pi/4)=1$ và kiểm điều kiện xác định của mọi nghiệm.`,R`$${a}x-\pi/4=\pi/4+k\pi$, nên $x=\pi/(2\cdot${a})+k\pi/${a}$. Góc trong tan tại các nghiệm là $\pi/4+k\pi$, cos khác không.`, 'Giữ nguyên góc có cả hằng số dịch.');},
 sequence:s=>{const a=n(s);return challenge(R`Hai mô tả đều bắt đầu $${a},${a+2},${a+4}$: dãy thứ nhất có đúng ba số hạng; dãy thứ hai có $u_n=${a}+2(n-1)$ với mọi $n\ge1$. Có thể coi chúng là cùng một dãy không? Viết miền chỉ số của từng dãy.`,R`Không cùng một dãy vì miền chỉ số khác nhau. Dãy đầu có miền $\{1,2,3\}$; dãy sau là $\mathbb N^*$. Ba giá trị đầu trùng không đủ đồng nhất hai hàm trên hai miền khác nhau.`, 'So sánh cả quy luật lẫn miền chỉ số.');},
 monotone:s=>{const a=n(s);return challenge(R`Với $u_n=${a}+m/(n+1)$, $n\ge1$, tìm điều kiện của $m$ để dãy tăng nghiêm ngặt, giảm nghiêm ngặt hoặc không đổi.`,R`$u_{n+1}-u_n=-m/((n+1)(n+2))$. Dãy tăng khi $m<0$, giảm khi $m>0$, không đổi khi $m=0$.`, 'Giữ tham số khi xét dấu hiệu hai số hạng.');},
 arithmetic:s=>{const a=n(s),d=1+s%4,N=8+s%5;return challenge(R`Cấp số cộng có $u_1=${a}$, $d=${d}$. Số $${a+(N-1)*d}$ là số hạng thứ mấy? Nêu điều kiện chỉ số cần kiểm.`,R`Giải $${a}+d(n-1)=${a+(N-1)*d}$ với $d=${d}$ cho $n=${N}$; đây là số nguyên dương.`, 'Đổi bài toán tìm giá trị thành bài toán tìm chỉ số.');},
 arithmeticSum:s=>{const a=n(s),N=6+s%5,d=2;return challenge(R`Cấp số cộng có công sai $2$, tổng ${N} số hạng đầu bằng $${N*(2*a+(N-1)*d)/2}$. Tìm số hạng đầu.`,R`$S_n=n[2u_1+(n-1)d]/2$. Thay số và giải phương trình tuyến tính được $u_1=${a}$.`, 'Viết tổng theo số hạng đầu chưa biết.');},
 geometric:s=>{const a=n(s);return challenge(R`Cấp số nhân có $u_1=${a}$ và $u_3=${4*a}$. Có xác định duy nhất công bội không? Liệt kê mọi khả năng rồi tìm $u_2$.`,R`$q^2=4$, nên $q=2$ hoặc $q=-2$. Tương ứng $u_2=${2*a}$ hoặc $u_2=-${2*a}$. Không được chỉ lấy căn dương.`, 'Số mũ chẵn có thể mất thông tin dấu.');},
 geometricSum:s=>{const a=n(s);return challenge(R`Hai kế hoạch trả thưởng bốn vòng: A trả $${a}$ xu mỗi vòng; B trả $${a},${2*a},${4*a},${8*a}$ xu. So sánh tổng, nêu vì sao không thể chỉ so khoản vòng đầu.`,R`A tổng $${4*a}$; B tổng $${15*a}$. B hơn $${11*a}$, do quy luật tăng khác nhau dù khoản đầu giống nhau.`, 'Tính toàn bộ khoản thưởng theo từng quy luật.');},
 spatialAxioms:s=>{const a=n(s);return challenge(R`Có $${a}$ điểm trên đường $d$, thêm hai điểm $A,B$ ngoài $d$. Luôn có một mặt phẳng chứa tất cả các điểm không? Nêu điều kiện cần và đủ theo hai mặt phẳng $(d,A)$, $(d,B)$.`,R`Không luôn có. Cần và đủ $(d,A)=(d,B)$, tương đương $B\in(d,A)$. Nếu hai mặt phẳng khác nhau, không có một mặt phẳng chứa cả đường và cả hai điểm.`, 'Đường và một điểm ngoài đường đã xác định duy nhất một mặt phẳng.');},
 planeIntersection:s=>{const a=n(s);return challenge(R`Hình chóp $S.ABCD$ có đáy hình thang $AB\parallel CD$, $AB=${a+2}$, $CD=${a}$. Hai cạnh $AD,BC$ kéo dài cắt tại $I$. Tìm $(SAD)\cap(SBC)$ và giải thích việc dùng phần kéo dài.`,R`$S$ chung; $I\in AD\subset(SAD)$ và $I\in BC\subset(SBC)$. Giao tuyến là $SI$. Mặt phẳng chứa toàn bộ đường thẳng chứ không chỉ đoạn cạnh.`, 'Tìm điểm chung thứ hai trên các đường của đáy, kể cả phần kéo dài.');},
 tetrahedron:s=>{const a=n(s);return challenge(R`Trong tứ diện $SABC$, $M\in AB,N\in AC$ với $AM/AB=AN/AC=1/${a}$. Đường $MN$ có cắt $(SBC)$ không? Giải thích qua giao tuyến $(ABC)\cap(SBC)$.`,R`$MN\parallel BC$ và $MN\subset(ABC)$; giao tuyến hai mặt phẳng là $BC$. Vì $MN$ khác $BC$ và song song với nó, $MN$ không có điểm chung với $(SBC)$.`, 'So sánh với trường hợp hai tỉ lệ không bằng nhau.');},
 linesPosition:s=>{const a=n(s);return challenge(R`Trong hình chóp $S.ABCD$ có đáy hình bình hành, $AB=${a}$, $AD=${a+1}$, một bạn cho rằng $SA\parallel BC$ vì hình vẽ không thấy cắt nhau. Chứng minh hai đường chéo nhau.`,R`Nếu $SA$ đồng phẳng với $BC$ thì mặt phẳng đó chứa $A$ và $BC$, nên chính là mặt phẳng đáy; khi đó chứa $S$, mâu thuẫn hình chóp. Vì vậy chúng không đồng phẳng, là chéo nhau.`, 'Dùng phản chứng về mặt phẳng chứa đường và một điểm.');},
 parallelLines:s=>{const a=n(s);return challenge(R`Trong tứ diện $SABC$, $M\in SA,N\in SB$ có $SM/SA=1/${a}$, $SN/SB=1/${a+1}$. Có thể kết luận $MN\parallel AB$ không? Nêu lập luận.`,R`Không. Nếu $MN\parallel AB$, định lý Thales trong tam giác $SAB$ bắt buộc hai tỉ lệ bằng nhau, trái giả thiết.`, 'Kiểm điều kiện của đường trung bình hoặc định lý đảo trước kết luận.');},
 linePlane:s=>{const a=n(s);return challenge(R`Hình chóp $S.ABCD$ có đáy hình bình hành, $AB=${a}$. Ta có $AB\parallel CD$ và $CD\subset(ABCD)$. Vì sao không được kết luận $AB\parallel(ABCD)$? Viết điều kiện còn thiếu trong định lý.`,R`$AB$ nằm trong đáy nên có vô số điểm chung với đáy. Định lý cần đường cần xét không nằm trong mặt phẳng; song song theo định nghĩa đòi không có điểm chung.`, 'Phân biệt nằm trong mặt phẳng với không có giao điểm.');},
 linePlaneProperty:s=>{const a=n(s);return challenge(R`Trong hình chóp $S.ABCD$ có đáy hình bình hành, $AB=${a}$, lấy $M$ nằm trong đoạn $SA$, khác S và A. Mặt phẳng qua $M$ song song với đường $AB$ cắt mặt $(SAB)$ theo đường nào? Vì sao các dữ kiện này chưa xác định duy nhất mặt phẳng đó?`,R`Giao tuyến là đường qua $M$ và song song $AB$. M ở trong SA nên M không thuộc AB; mặt phẳng song song AB không thể trùng (SAB), vì (SAB) chứa AB. Có nhiều mặt phẳng qua giao tuyến này, khác (SAB), và không có điểm chung với AB; chưa xác định duy nhất một mặt phẳng.`, 'Tách điều đủ để xác định đường khỏi điều đủ để xác định mặt phẳng.');},
 planesParallel:s=>{const a=n(s);return challenge(R`Trong tứ diện $SABC$, $M,N,P$ trên $SA,SB,SC$ có $SM/SA=SN/SB=1/${a}$ nhưng $SP/SC=1/${a+1}$. Vì sao một cặp $MN\parallel AB$ chưa đủ để kết luận $(MNP)\parallel(ABC)$?`,R`Nếu hai mặt phẳng song song, thiết diện trên các tia từ $S$ phải có cùng tỉ lệ; ở đây tỉ lệ của $P$ khác. Có một hướng song song nhưng thiếu hướng thứ hai.`, 'Thử dùng hệ quả Thales cho một thiết diện song song.');},
 thales:s=>{const a=n(s);return challenge(R`Ba mặt phẳng song song cắt hai cát tuyến tại $A,B,C$ và $A',B',C'$. Biết $AB:BC=2:3$, $A'C'=${5*a}$. Tìm $A'B'$ và $B'C'$.`,R`Các đoạn tương ứng có tỉ lệ $2:3$, tổng $5a$, nên $A'B'=${2*a}$ và $B'C'=${3*a}$.`, 'Tỉ lệ giữa hai phần khác với tỉ lệ trên tổng.');},
 prism:s=>{const a=n(s);return challenge(R`Trong hình hộp $ABCD.A'B'C'D'$, $AB=${a}$, gọi $O,O'$ là giao điểm hai đường chéo của hai đáy. Chứng minh $OO'\parallel AA'$ mà không giả sử hình hộp đứng.`,R`Trong mặt phẳng chéo $ACC'A'$, tứ giác $ACC'A'$ là hình bình hành; $O,O'$ là trung điểm hai cạnh đối $AC,A'C'$. Đường nối hai trung điểm này song song và bằng $AA'$.`, 'Chọn một mặt phẳng chéo chứa cả hai tâm đáy.');},
 projection:s=>{const a=n(s);return challenge(R`Ảnh chiếu song song của tam giác $ABC$ là tam giác $A'B'C'$ không suy biến. Điểm $M\in BC$ với $BM:MC=1:${a}$. Chứng minh ảnh đường $AM$ đi qua điểm chia $B'C'$ cùng tỉ lệ; có bảo toàn góc $BAM$ không?`,R`Tính thẳng hàng và tỉ số cùng đường được bảo toàn, nên $M'\in B'C'$ với $B'M':M'C'=1:${a}$; ảnh $AM$ là $A'M'$. Góc không được bảo toàn nói chung.`, 'Liệt kê đúng các tính chất được bảo toàn và phần không được bảo toàn.');},
 grouped:s=>{const a=n(s);return challenge(R`Hai mẫu khác nhau cùng cho tần số $3,3$ ở hai nhóm $[${a};${a+5})$, $[${a+5};${a+10})$. Hãy xây dựng hai mẫu có trung bình chính xác khác nhau và giải thích điều bị mất khi ghép nhóm.`,R`Có thể dùng mẫu $${a},${a},${a},${a+5},${a+5},${a+5}$ và mẫu $${a+4},${a+4},${a+4},${a+9},${a+9},${a+9}$. Trung bình khác nhau dù bảng nhóm giống nhau; dữ liệu vị trí trong nhóm đã mất.`, 'Chọn các giá trị sát đầu trái hoặc sát đầu phải trong cùng nhóm.');},
 groupedMean:s=>{const a=n(s);return challenge(R`Hai nhóm $[${a};${a+4})$, $[${a+4};${a+8})$ có tần số $m,3m$ với $m>0$. Trung bình ghép nhóm có phụ thuộc $m$ không? Tính giá trị.`,R`Trung điểm $${a+2},${a+6}$; trung bình bằng $[m(${a+2})+3m(${a+6})]/4m=${a+5}$, không phụ thuộc quy mô chung $m$.`, 'Rút nhân tử chung tần số trước khi tính.');},
 groupedMedian:s=>{const a=n(s);return challenge(R`Ba nhóm $[${a};${a+4})$, $[${a+4};${a+8})$, $[${a+8};${a+12})$ có tần số $2,10,4$. Tính trung vị rồi so với trung điểm nhóm chứa trung vị.`,R`Vị trí giữa $8$ nằm nhóm hai; $M_e=${a+4}+(8-2)4/10=${a+6.4}$. Khác trung điểm $${a+6}$ vì vị trí nội suy không ở giữa tần số nhóm.`, 'Không dùng tính đối xứng khi các tần số không đối xứng.');},
 quartiles:s=>{const a=n(s);return challenge(R`Ba nhóm $[${a};${a+4})$, $[${a+4};${a+8})$, $[${a+8};${a+12})$ có tần số $4,8,4$. Tính $Q_1,Q_3$ rồi giải thích khoảng giữa chứa xấp xỉ bao nhiêu phần trăm mẫu.`,R`Vị trí $4$ và $12$ cho $Q_1=${a+4}$, $Q_3=${a+8}$. Khoảng giữa hai tứ phân vị chứa khoảng $50\%$ dữ liệu.`, 'Theo dõi các vị trí một phần tư và ba phần tư.');},
 mode:s=>{const a=n(s);return challenge(R`Ba nhóm cùng độ rộng $4$, nhóm giữa có cận trái $${a}$, tần số ba nhóm lần lượt $2,10,6$. Tính mốt và giải thích vì sao nó lệch khỏi trung điểm nhóm mốt.`,R`$M_o=${a}+8/(8+4)\cdot4=${a}+8/3$. Hai chênh lệch không bằng nhau nên mốt không ở trung điểm.`, 'Tính chênh lệch tần số ở hai phía riêng biệt.');},
 limitSequence:s=>{const a=n(s);return challenge(R`So sánh giới hạn của $u_n=(${a}n+1)/(n^2+1)$ và $v_n=(${a}n^2+1)/(n+1)$. Vì sao không dùng cùng kết quả tỉ số hệ số?`,R`$u_n\to0$ vì bậc tử thấp hơn; $v_n\to+\infty$ vì bậc tử cao hơn và hệ số dẫn đầu dương. Tỉ số hệ số chỉ dùng trực tiếp khi cùng bậc.`, 'So bậc trước khi so hệ số.');},
 infiniteSeries:s=>{const a=n(s);return challenge(R`So sánh khả năng có tổng hữu hạn của hai cấp số nhân vô hạn có số hạng đầu $${a}$, công bội lần lượt $1/2$ và $2$. Tính tổng nếu tồn tại.`,R`Với $q=1/2$, tổng $2\cdot${a}=${2*a}$. Với $q=2$, tổng riêng tăng không bị chặn; không có tổng hữu hạn theo công thức lùi vô hạn.`, 'Điều kiện trị tuyệt đối công bội quyết định trước phép thế công thức.');},
 infinitySequence:s=>{const a=n(s);return challenge(R`Tìm giới hạn của $u_n=n^2+(-1)^n${a}n$. Hạng đổi dấu có làm dãy mất giới hạn không?`,R`$u_n=n^2[1+(-1)^n${a}/n]$, ngoặc tiến về $1>0$, nên $u_n\to+\infty$. Hạng bậc hai chi phối hạng dao động bậc một.`, 'So độ lớn hạng dao động với hạng chính.');},
 functionLimit:s=>{const a=n(s);return challenge(R`Tính $\lim_{x\to${a}}(x^3-${a**3})/(x-${a})$ bằng phân tích đại số, không dùng đạo hàm.`,R`Thương bằng $x^2+${a}x+${a*a}$ ngoài điểm xét; giới hạn bằng $${3*a*a}$.`, 'Dùng hằng đẳng thức hiệu hai lập phương.');},
 oneSided:s=>{const a=n(s);return challenge(R`Cho $f(x)=x+${a}$ khi $x<1$, $f(x)=mx+2$ khi $x\ge1$. Tìm $m$ để giới hạn hai phía tại $1$ tồn tại.`,R`Giới hạn trái $${a+1}$, phải $m+2$; cần $m=${a-1}$.`, 'Đặt hai giới hạn một bên bằng nhau.');},
 infinityFunction:s=>{const a=n(s);return challenge(R`Tính $\lim_{x\to-\infty}\sqrt{x^2+${a}}/x$. Giải thích vai trò của dấu giá trị tuyệt đối.`,R`$\sqrt{x^2+${a}}=|x|\sqrt{1+${a}/x^2}$. Khi $x<0$, $|x|/x=-1$, nên giới hạn $-1$.`, 'Căn của bình phương trả về trị tuyệt đối, không phải luôn chính biến.');},
 poleLimit:s=>{const a=n(s);return challenge(R`Tìm các giới hạn một bên của $(${a}-x)/(x-${a})^2$ khi $x\to${a}$. So với trường hợp tử là hằng số dương.`,R`Ngoài điểm xét, biểu thức bằng $-1/(x-${a})$. Trái cho $+\infty$, phải cho $-\infty$. Tử cũng đổi dấu nên mẫu bình phương dương không đủ quyết định dấu thương.`, 'Rút gọn nhưng vẫn giữ hướng tiến tới.');},
 continuityPoint:s=>{const a=n(s);return challenge(R`Cho $f(x)=x+${a}$ nếu $x<1$ và $f(x)=mx+2$ nếu $x\ge1$. Tìm $m$ để hàm liên tục tại $1$; nêu đủ ba điều cần kiểm.`,R`Giá trị tại điểm $f(1)=m+2$ xác định. Hai giới hạn trái/phải bằng nhau khi $m=${a-1}$; khi đó đều bằng $f(1)=${a+1}$.`, 'Đừng dừng ở việc hai giới hạn một bên bằng nhau; so thêm giá trị hàm.');},
 continuityInterval:s=>{const a=n(s);return challenge(R`Hàm $f(x)=\sqrt{x-${a}}/(x-${a}-1)$ xác định ở đâu? Nêu các khoảng mở mà hàm liên tục.`,R`Cần $x\ge${a}$ và $x\ne${a+1}$. Các khoảng mở là $(${a};${a+1})$, $(${a+1};+\infty)$; tại cận trái xét liên tục một phía nếu cần.`, 'Kết hợp điều kiện căn với điều kiện mẫu.');},
 integerPower:s=>{const a=n(s);return challenge(R`Rút gọn $\sqrt{(x-${a})^2}$ trên hai miền $x\ge${a}$ và $x<${a}$. Vì sao không thể bỏ dấu căn thành $x-${a}$ trên toàn trục?`,R`Biểu thức bằng $|x-${a}|$, tức $x-${a}$ trên miền thứ nhất và $${a}-x$ trên miền thứ hai. Căn bậc hai số học không âm.`, 'Kiểm dấu biểu thức trong trị tuyệt đối.');},
 realPower:s=>{const a=n(s);return challenge(R`Với $x>0$, rút gọn $(x^{1/2}x^{1/3})^6/x^{${a}}$. Nêu số mũ cuối cùng và điều kiện dùng quy tắc.`,R`Trong ngoặc số mũ $5/6$, sau lũy thừa là $5$; kết quả $x^{${5-a}}$. Điều kiện $x>0$ cho phép các lũy thừa hữu tỉ và phép chia.`, 'Nhân cùng cơ số thì cộng mũ; lũy thừa của lũy thừa thì nhân mũ.');},
 logarithm:s=>{const a=2+s%4;return challenge(R`Giải $\log_${a}(x-1)=2$. Nêu điều kiện trước khi biến đổi và kiểm lại nghiệm.`,R`Điều kiện $x>1$. Theo định nghĩa $x-1=${a}^2$, nên $x=${a*a+1}$, thỏa điều kiện.`, 'Chuyển từ lôgarit sang lũy thừa theo đúng cơ số.');},
 logBase:s=>{const a=2+s%5;return challenge(R`Biết $t=\log_2 ${a}$. Biểu diễn $\log_${a}8$ theo $t$; nêu điều kiện mẫu khác không.`,R`$\log_${a}8=\log_2 8/\log_2 ${a}=3/t$. Vì $${a}>1$, $t>0$.`, 'Đổi cả hai lôgarit về cùng một cơ số.');},
};
for(const [id,question] of Object.entries(advanced)){const normal=bank[id].question;bank[id].question=(s,d)=>d===3?question(s):normal(s,d);}

const hkiIds = Object.keys(bank);
const nc = (title, statement, teach, error, question) => concept(title, statement, 2, [], teach, error, question);
const scaffold = (strategy, first, example) => hints('Ghi dữ kiện và điều kiện trước khi làm.', strategy, first, example);
const pick = (prompt, options, solution, help) => {
 assert.equal(options.filter(row => row[1]).length, 1, prompt);
 assert.equal(new Set(options.map(row => row[0])).size, options.length, prompt);
 numericChecks++;
 const offset=prompt.length%options.length,ordered=[...options.slice(offset),...options.slice(0,offset)];
 return choice(prompt, ordered.map(row => row[0]), ordered.findIndex(row => row[1]), solution, help);
};
const derivativeCheck = (fn, x, expected) => {
 const h = 0.0001, observed = (fn(x + h) - fn(x - h)) / (2 * h);
 assert.ok(Math.abs(observed - expected) < 0.00001 * Math.max(1, Math.abs(expected)), `${observed} != ${expected}`);
 numericChecks++;
};
const probability = (success, total) => success / total;
const hk = {
 exDomain: nc('Tập xác định và chiều biến thiên của hàm số mũ', 'Xác định tập xác định và chiều biến thiên của hàm số mũ theo cơ số.', R`GV lập bảng giá trị của $2^x$ và $(1/2)^x$ tại ba giá trị liên tiếp. HS dự đoán, GV chốt: cơ số dương khác $1$, miền xác định $\mathbb R$; cơ số lớn hơn $1$ cho đồng biến, nằm giữa $0$ và $1$ cho nghịch biến.`, 'Lấy điều kiện số mũ dương; quên đổi chiều khi cơ số dưới một.', (s,d) => {
  const a=2+s%5,k=n(s),down=d%2===1,baseText=down?frac(1,a):String(a);
  return pick(R`Cho $f(x)=(${baseText})^{x-${k}}$. Chọn tập xác định và chiều biến thiên đúng.`, [[R`$D=\mathbb R$; đồng biến.`,!down],[R`$D=\mathbb R$; nghịch biến.`,down],[R`$D=(${k};+\infty)$; đồng biến.`,false],[R`$D=(${k};+\infty)$; nghịch biến.`,false]], R`Số mũ $x-${k}$ nhận mọi số thực, nên $D=\mathbb R$. Cơ số ${down?'nằm giữa $0$ và $1$, nên hàm nghịch biến':'lớn hơn $1$, nên hàm đồng biến'}.`, scaffold('So cơ số với một; không đặt điều kiện dương cho số mũ.','Viết điều kiện của cơ số, rồi xét mọi giá trị của biến.',R`Ví dụ khác: $3^{x+37}$ vẫn xác định khi số mũ âm.`));
 }),
 exGraph: nc('Đồ thị hàm số mũ', 'Lập bảng điểm và phác đồ thị hàm số mũ, nhận biết chiều biến thiên và giới hạn ở một phía.', R`Từ bảng giá trị, GV vẽ đồ thị qua các điểm, nhấn mạnh giá trị hàm dương và trục hoành là tiệm cận ngang của đồ thị cơ bản. Với biểu thức dịch chuyển, HS dịch điểm đặc trưng rồi đối chiếu.`, 'Vẽ đồ thị cắt đường tiệm cận; nhầm vị trí điểm có số mũ bằng không.', (s,d) => {
  const a=2+s%4,k=n(s),c=d===0?0:1+s%3;
  return open(R`Phác đồ thị $y=${a}^{x-${k}}+${c}$ trong vở. Tính giá trị tại $x=${k-1},${k},${k+1}$; nêu chiều biến thiên và đường thẳng mà đồ thị tiến gần khi $x\to-\infty$.`,R`Ba tung độ lần lượt $${frac(1,a)}+${c}$, $${c+1}$, $${a+c}$. Hàm đồng biến trên $\mathbb R$; khi $x\to-\infty$, $y\to${c}$ và luôn $y>${c}$. Đường thẳng cần nêu là $y=${c}$.`,scaffold('Chọn các số mũ âm một, không, một.','Thay giá trị ở giữa để có số mũ bằng không.',R`Ví dụ khác: với $y=2^{x-37}$, điểm có hoành độ $37$ được tìm bằng cách tính $2^0$.`),['Ba điểm đúng; hình vẽ tăng và nằm trên đường giới hạn.','Giải thích bằng cơ số và giá trị của lũy thừa.']);
 }),
 lgDomain: nc('Tập xác định và biến thiên của hàm số lôgarit','Tìm điều kiện của biểu thức dưới dấu lôgarit và xét chiều biến thiên theo cơ số.', R`GV đối chiếu $y=a^x$ với $y=\log_a x$ qua việc đổi vai trò đầu vào và đầu ra. Chốt điều kiện đối số dương; cơ số lớn hơn một thì đồng biến, cơ số dưới một thì nghịch biến.`, 'Đặt đối số không âm; chỉ kiểm cơ số mà bỏ điều kiện đối số.', (s,d) => {
  const a=2+s%5,k=n(s),down=d%2===1,b=down?frac(1,a):String(a);
  return pick(R`Hàm $y=\log_{${b}}(x-${k})$ có tập xác định và chiều biến thiên nào?`,[[R`$(${k};+\infty)$; ${down?'nghịch':'đồng'} biến.`,true],[R`$[${k};+\infty)$; ${down?'nghịch':'đồng'} biến.`,false],[R`$\mathbb R$; ${down?'nghịch':'đồng'} biến.`,false],[R`$(${k};+\infty)$; ${down?'đồng':'nghịch'} biến.`,false]],R`Cần $x-${k}>0$, tức $x>${k}$. Hàm ${down?'nghịch':'đồng'} biến trên miền này vì cơ số ${down?'nằm giữa $0$ và $1$':'lớn hơn $1$'}.`,scaffold('Tách điều kiện đối số với điều kiện cơ số.','Giải bất đẳng thức nghiêm cho đối số.',R`Ví dụ khác: $\log_3(x+37)$ đòi hỏi $x+37>0$.`));
 }),
 lgGraph: nc('Đồ thị hàm số lôgarit','Lập các điểm đặc trưng và phác đồ thị hàm số lôgarit trên đúng miền xác định.', R`GV cho HS tìm đầu vào khi giá trị lôgarit bằng âm một, không, một, rồi phác đường cong. Chốt đồ thị không có điểm tại biên miền xác định; phân biệt trục tiệm cận và điểm cắt trục.`, 'Cho đồ thị đi qua biên miền xác định; đổi sai hoành và tung độ.', (s,d) => {
  const a=2+s%4,k=n(s),c=d%3;
  return open(R`Với $y=\log_${a}(x-${k})+${c}$, xác định miền, ba điểm ứng với $x-${k}=1/${a},1,${a}$, rồi phác đồ thị. Nêu đường thẳng đồ thị tiến gần khi $x\to${k}^+$.`,R`Miền $x>${k}$. Ba điểm $(${k}+1/${a};${c-1})$, $(${k+1};${c})$, $(${k+a};${c+1})$. Hàm đồng biến; $y\to-\infty$ khi $x\to${k}^+$, nên đường giới hạn là $x=${k}$.`,scaffold('Chọn đối số là các lũy thừa đơn giản của cơ số.','Giải ba phương trình cho hoành độ trước khi tính tung độ.',R`Ví dụ khác: $\log_2(x-37)=0$ tương đương $x-37=2^0$.`),['Miền và ba điểm đúng.','Đồ thị tăng, không chạm đường biên; mô tả giới hạn một phía đúng.']);
 }),
 exEq: nc('Phương trình mũ','Giải phương trình mũ bằng đưa về cùng cơ số hoặc dùng tính đơn điệu.', R`GV viết hai lũy thừa cùng cơ số dương khác một; yêu cầu HS giải thích vì sao có thể so số mũ. Chốt điều kiện cơ số và thay nghiệm kiểm lại, không biến tổng thành tích.`, 'Đồng nhất số mũ khi cơ số khác nhau; bỏ hệ số của biến.', (s,d) => {
  const a=2+s%4,k=n(s),m=d===0?1:2+s%3,b=1+s%4,exp=m*k+b;
  return numeric(R`Giải $${a}^{${m}x+${b}}=${a}^{${exp}}$. Nhập nghiệm $x$; trong vở giải thích phép so số mũ.`,k,R`Cơ số $${a}>1$, nên $${m}x+${b}=${exp}$, suy ra $x=${k}$. Thế lại cho hai số mũ bằng nhau.`,scaffold('Đưa hai vế về cùng một cơ số hợp lệ.','So hai biểu thức số mũ rồi giải phương trình bậc nhất.',R`Ví dụ khác: $3^{2t+37}=3^{41}$ dẫn tới $2t+37=41$.`),(exp-b)/m);
 }),
 lgEq: nc('Phương trình lôgarit','Giải phương trình lôgarit và đối chiếu điều kiện xác định trước kết luận.', R`GV viết điều kiện đối số dương trước mỗi phép biến đổi. Dùng định nghĩa lôgarit để đổi sang lũy thừa; chốt nghiệm phải thỏa điều kiện ban đầu, đặc biệt khi có tổng hoặc hiệu lôgarit.`, 'Nhận cả nghiệm làm đối số không dương.', (s,d) => {
  const a=2+s%4,k=n(s),m=d===0?1:2,exp=1+s%3,shift=a**exp-m*k;
  return numeric(R`Giải $\log_${a}(${m}x${shift<0?'':'+'}${shift})=${exp}$. Nhập nghiệm $x$, ghi điều kiện trong vở.`,k,R`Điều kiện $${m}x${shift<0?'':'+'}${shift}>0$. Theo định nghĩa, đối số bằng $${a}^{${exp}}=${a**exp}$, nên $x=${k}$; đối số tại nghiệm dương.`,scaffold('Điều kiện của lôgarit áp dụng cho toàn bộ đối số.','Đổi về phương trình có đối số bằng một lũy thừa.',R`Ví dụ khác: $\log_2(t+37)=41$ dẫn tới $t+37=2^{41}$, kèm $t+37>0$.`),(Math.exp(exp*Math.log(a))-shift)/m);
 }),
 exIneq: nc('Bất phương trình mũ','Giải bất phương trình mũ, đổi chiều đúng khi cơ số nhỏ hơn một.', R`Cho hai biểu thức có cùng cơ số, dùng bảng tăng/giảm để quyết định chiều so số mũ. GV yêu cầu kiểm một giá trị thuộc tập nghiệm và một giá trị ngoài tập nghiệm.`, 'Giữ nguyên chiều bất đẳng thức với cơ số dưới một.', (s,d) => {
  const a=2+s%5,k=n(s),down=d%2===1,b=down?frac(1,a):String(a),rhs=2*k+1;
  const correct=down?R`$x>${k}$`:R`$x<${k}$`;
  assert.equal((down?1/a:a)**(2*(k-1)+1)<(down?1/a:a)**rhs,!down);numericChecks++;
  return pick(R`Giải $(${b})^{2x+1}<(${b})^{${rhs}}$.`,[[correct,true],[down?R`$x<${k}$`:R`$x>${k}$`,false],[R`$x=${k}$`,false],[R`$x\ne${k}$`,false]],R`Hàm mũ ${down?'nghịch':'đồng'} biến, nên $2x+1${down?'>':'<'}${rhs}$. Tập nghiệm: ${correct}.`,scaffold('Xét cơ số trước khi so số mũ.','Viết chiều so sánh giữa hai số mũ, chưa giải ngay.',R`Ví dụ khác: $(1/3)^u<(1/3)^{37}$ đòi hỏi số mũ bên trái lớn hơn số mũ bên phải.`));
 }),
 lgIneq: nc('Bất phương trình lôgarit','Giải bất phương trình lôgarit, kết hợp điều kiện xác định với tính đơn điệu.', R`GV chia bảng thành cột điều kiện và cột bất phương trình. HS lấy giao hai miền cuối cùng; với cơ số dưới một phải đảo chiều khi bỏ lôgarit.`, 'Đảo chiều đúng nhưng quên đối số dương.', (s,d) => {
  const a=2+s%4,k=n(s),down=d%2===1,b=down?frac(1,a):String(a);
  return open(R`Giải $\log_{${b}}(x-${k})<1$. Viết tập nghiệm, kiểm một điểm thuộc tập nghiệm.`,down?R`Điều kiện $x>${k}$. Vì cơ số $1/${a}<1$, cần $x-${k}>1/${a}$. Tập nghiệm $(${k}+1/${a};+\infty)$. Điểm $x=${k+1}$ thuộc tập nghiệm vì lôgarit bằng $0<1$.`:R`Điều kiện $x>${k}$. Vì cơ số $${a}>1$, cần $x-${k}<${a}$. Tập nghiệm $(${k};${k+a})$. Điểm $x=${k+1}$ thuộc tập nghiệm vì lôgarit bằng $0<1$.`,scaffold('Viết điều kiện xác định rồi so đối số theo cơ số.','Biểu diễn số ở vế phải dưới dạng lôgarit cùng cơ số.',R`Ví dụ khác: với cơ số dưới một, $\log_{1/3}u<\log_{1/3}37$ dẫn tới $u>37$.`),['Điều kiện xác định đúng.','Chiều bất đẳng thức và giao miền đúng.','Điểm kiểm thuộc miền và thỏa bất phương trình.']);
 }),
 lineAngle: nc('Góc giữa hai đường thẳng','Xác định góc giữa hai đường thẳng trong không gian qua hai đường song song cắt nhau.', R`GV dựng hai đường qua cùng một điểm lần lượt song song với hai đường đã cho; đánh dấu hai góc bù nhau. Chốt góc giữa hai đường nằm trong đoạn từ không đến vuông, kể cả khi hai đường ban đầu chéo nhau.`, 'Lấy góc tù làm góc giữa hai đường; chỉ định nghĩa góc cho hai đường cắt nhau.', (s,d) => {
  const angle=25+s%55,obtuse=d%2===1,shown=obtuse?180-angle:angle;
  return numeric(R`Qua $O$ dựng $a'\parallel a$, $b'\parallel b$. Một góc tạo bởi $a',b'$ bằng $${shown}^\circ$. Tìm góc giữa $a,b$ theo độ; nêu vì sao vị trí chéo nhau của $a,b$ không cản trở cách làm.`,angle,R`Hai góc kề bù là $${shown}^\circ$ và $${180-shown}^\circ$. Góc giữa hai đường lấy giá trị không lớn hơn $90^\circ$, bằng $${angle}^\circ$.`,scaffold('Góc giữa hai đường không lớn hơn góc vuông.','Tìm cả hai góc kề bù rồi chọn góc phù hợp.',R`Ví dụ khác: khi hai tia tạo góc $137^\circ$, góc kề bù được tính bằng $180^\circ-137^\circ$.`),Math.acos(Math.abs(Math.cos(shown*Math.PI/180)))*180/Math.PI);
 }),
 linePerp: nc('Hai đường thẳng vuông góc','Chứng minh hai đường vuông góc bằng góc giữa chúng, phân biệt vuông góc và cắt nhau.', R`Dùng mô hình hình hộp chữ nhật: một cặp cạnh cắt nhau vuông góc, một cặp chéo nhau có góc vuông. GV chốt trong không gian hai đường vuông góc không nhất thiết cắt nhau.`, 'Đòi hỏi hai đường vuông góc phải có giao điểm.', (s,d) => {
  const a=n(s),b=2+s%5;
  return open(R`Hình hộp chữ nhật $ABCD.A'B'C'D'$ có $AB=${a}$ cm, $AD=${b}$ cm. Chứng minh $AB\perp B'C'$ và nêu chúng cắt nhau hay chéo nhau. ${d>=2?'So sánh với cặp $AB,BC$.':''}`,R`$B'C'\parallel BC$ và $AB\perp BC$ vì đáy là hình chữ nhật; do đó góc giữa $AB,B'C'$ bằng $90^\circ$. Hai đường không cắt nhau, không song song, nên chéo nhau. $AB,BC$ cắt nhau vuông góc tại $B$.`,scaffold('Tìm cạnh đáy song song với cạnh trên.','Thay một đường bằng đường song song đi qua điểm chung.',R`Ví dụ khác: trong hộp chữ nhật khác, cạnh thẳng đứng vuông góc với cạnh ngang dù hai cạnh được chọn không chung đỉnh.`),['Chỉ đúng cặp song song và góc vuông ở đáy.','Phân biệt cắt nhau và chéo nhau; không dựa vào hình vẽ phối cảnh.']);
 }),
 linePlanePerp: nc('Điều kiện đường thẳng vuông góc mặt phẳng','Dùng hai đường cắt nhau trong mặt phẳng để chứng minh đường thẳng vuông góc mặt phẳng.', R`GV cho HS so sánh hai giả thiết: vuông góc một đường và vuông góc hai đường cắt nhau. Chốt đường thứ hai phải nằm cùng mặt phẳng, cắt đường thứ nhất; hai đường song song chưa đủ.`, 'Kiểm hai đường song song thay cho hai đường cắt nhau.', (s,d) => {
  const a=n(s),b=2+s%5;
  return open(R`Cho $SA\perp AB$, $SA\perp AD$, với $ABCD$ là hình chữ nhật, $AB=${a}$ cm, $AD=${b}$ cm, $S$ ngoài $(ABCD)$. Chứng minh $SA\perp(ABCD)$ rồi suy ra $SA\perp BD$. ${d>=2?R`Giải thích vì sao chỉ có $SA\perp AB$ là chưa đủ.`:''}`,R`$AB,AD$ thuộc $(ABCD)$ và cắt nhau tại $A$. $SA$ vuông góc cả hai nên $SA\perp(ABCD)$. Vì $BD$ nằm trong mặt phẳng đó, $SA\perp BD$. Vuông góc một đường chưa xác định được hướng pháp tuyến của cả mặt phẳng.`,scaffold('Chỉ rõ mặt phẳng đích và các đường nằm trong đó.','Chọn hai đường cắt nhau mà đường đã cho cùng vuông góc.',R`Ví dụ khác: muốn chứng minh một cột vuông góc mặt sàn, cần kiểm hai hướng cắt nhau trên sàn.`),['Hai đường kiểm tra thuộc mặt phẳng và cắt nhau.','Dẫn định lý đúng rồi suy ra quan hệ với đường còn lại.']);
 }),
 perpProperties: nc('Tính chất của đường vuông góc mặt phẳng','Sử dụng tính duy nhất của đường vuông góc mặt phẳng qua một điểm và định lý ba đường vuông góc.', R`GV chỉ chân đường vuông góc, hình chiếu của đường xiên. HS ghi rõ đường nào nằm trong mặt phẳng trước khi dùng quan hệ vuông góc; không suy chiều cao từ nét đứng trên bản vẽ.`, 'Nhầm đường xiên với đường cao; dùng ba đường vuông góc khi chưa xác định hình chiếu.', (s,d) => {
  const a=n(s),b=2+s%4;
  return open(R`Cho $SA\perp(ABC)$, tam giác $ABC$ vuông tại $B$, $AB=${a}$ cm, $BC=${b}$ cm. Chứng minh $BC\perp(SAB)$ và $BC\perp SB$. ${d>=2?'Đường thẳng qua $B$ vuông góc $(ABC)$ có song song $SA$ không? Giải thích.':''}`,R`$BC\perp AB$ từ đáy và $BC\perp SA$ vì $SA\perp(ABC)$. Hai đường $AB,SA$ cắt nhau trong $(SAB)$, nên $BC\perp(SAB)$, suy ra $BC\perp SB$. Đường qua $B$ vuông góc cùng mặt phẳng thì song song $SA$.`,scaffold('Ghi hai quan hệ vuông góc với hai đường trong mặt phẳng cần xét.','Từ đường cao suy ra quan hệ với một cạnh đáy.',R`Ví dụ khác: hai cột cùng vuông góc một sàn phẳng có hướng song song.`),['Suy ra hai quan hệ vuông góc hợp lệ.','Nêu hai đường cắt nhau và áp dụng định lý đúng.']);
 }),
 parallelPerp: nc('Liên hệ song song và vuông góc','Vận dụng quan hệ song song để chuyển một quan hệ vuông góc đường–mặt phẳng.', R`GV yêu cầu đọc đủ giả thiết trước mỗi suy luận: hai đường cùng vuông góc một mặt phẳng thì song song; hai mặt phẳng cùng vuông góc một đường thì song song. Quan hệ vuông góc được giữ khi thay bằng đối tượng song song phù hợp.`, 'Suy hai mặt phẳng cùng vuông góc mặt phẳng thứ ba thì song song.', (s,d) => {
  const k=n(s);
  return open(R`Trong mô hình gồm ${k} thanh, chọn hai thanh $a,b$ và hai tấm phẳng $(P),(Q)$. Biết $a\perp(P)$, $b\parallel a$, $(Q)\parallel(P)$. Suy ra quan hệ của $b$ với $(P)$ và $(Q)$, nêu định lý. ${d>=2?'Hai mặt phẳng cùng vuông góc một mặt phẳng khác có luôn song song không? Cho phản ví dụ.':''}`,R`Từ $b\parallel a$ và $a\perp(P)$ suy ra $b\perp(P)$. Vì $(Q)\parallel(P)$, tiếp tục suy ra $b\perp(Q)$. Hai bức tường kề nhau đều vuông góc sàn nhưng cắt nhau, nên mệnh đề bổ sung không đúng.`,scaffold('Tách các giả thiết về đường và về mặt phẳng.','Chuyển quan hệ vuông góc từ đường đã biết sang đường song song.',R`Ví dụ khác: một cột vuông góc mặt sàn cũng vuông góc mặt trần song song với sàn.`),['Hai kết luận kèm giả thiết đúng.','Nếu có phần phản ví dụ: mô hình thỏa giả thiết nhưng không thỏa kết luận.']);
 }),
 projectionPerp: nc('Phép chiếu vuông góc','Xác định hình chiếu vuông góc của điểm và đoạn thẳng lên mặt phẳng.', R`GV chiếu từng đầu mút của đoạn thẳng: điểm đã nằm trên mặt phẳng giữ nguyên, điểm ở ngoài đi theo đường vuông góc tới chân chiếu. Chốt hình chiếu của đoạn xiên là đoạn nối hai hình chiếu.`, 'Lấy giao điểm bất kỳ làm chân chiếu; cho mọi đoạn đều giữ độ dài.', (s,d) => {
  const a=n(s),h=2+s%5;
  return open(R`Cho hình chóp $S.ABC$ với $SA\perp(ABC)$, $AB=${a}$ cm và $SA=${h}$ cm. Xác định hình chiếu của $S$, $B$ và $SB$ lên $(ABC)$. Tính độ dài hình chiếu của $SB$. ${d>=2?'So sánh độ dài $SB$ với độ dài hình chiếu.':''}`,R`Chân chiếu của $S$ là $A$; $B$ giữ nguyên. Vì thế hình chiếu của $SB$ là $AB$, dài $${a}$ cm. $SB=\sqrt{${a*a+h*h}}>${a}$ cm do tam giác $SAB$ vuông tại $A$.`,scaffold('Tìm hình chiếu của từng đầu mút.','Dùng đường đã biết vuông góc mặt phẳng để tìm chân chiếu.',R`Ví dụ khác: một điểm trên mặt bàn có hình chiếu lên chính mặt bàn là bản thân điểm đó.`),['Ba hình chiếu chính xác.','Độ dài và đơn vị đúng; giải thích so sánh nếu được yêu cầu.']);
 }),
 linePlaneAngle: nc('Góc giữa đường thẳng và mặt phẳng','Xác định góc giữa đường xiên và hình chiếu của nó, tính tỉ số lượng giác trong tam giác vuông.', R`GV khoanh góc giữa đường xiên và đoạn hình chiếu, không khoanh góc với đường cao. Trong tam giác vuông, HS chọn đúng đối/kề/huyền rồi kiểm góc nằm từ không tới vuông.`, 'Lấy góc giữa đường xiên với đường cao.', (s) => {
  const a=2+s%11,h=3+s%7,ratio=h/a;
  assert.ok(Math.abs(ratio-Math.tan(Math.atan2(h,a)))<1e-9);numericChecks++;
  return open(R`Cho $SA\perp(ABC)$, $SA=${h}$ cm, $AB=${a}$ cm. Gọi $\alpha$ là góc giữa $SB$ và $(ABC)$. Xác định góc $\alpha$ bằng tên ba điểm và giải thích, rồi tính $\tan\alpha$.`,R`Hình chiếu của $SB$ là $AB$, nên $\alpha=\widehat{SBA}$. Tam giác $SAB$ vuông tại $A$, $\tan\alpha=SA/AB=${frac(h,a)}$.`,scaffold('Chiếu đường xiên xuống mặt phẳng.','Góc cần tìm ở đầu mút thuộc mặt phẳng.',R`Ví dụ khác: thanh nghiêng trên sàn tạo góc với bóng chiếu của nó; cạnh đối là độ cao, cạnh kề là chiều dài bóng.`),['Xác định đúng hình chiếu và tên góc.','Tỉ số lượng giác đúng cạnh đối, cạnh kề và giá trị.']);
 }),
 planeAngle: nc('Góc giữa hai mặt phẳng','Xác định góc giữa hai mặt phẳng bằng mặt cắt vuông góc giao tuyến.', R`GV dựng hai đường cùng vuông góc giao tuyến tại cùng một điểm, mỗi đường nằm trong một mặt phẳng. Chốt góc giữa hai mặt phẳng là góc không tù giữa hai đường này; góc nhìn phối cảnh không phải dữ kiện.`, 'Chọn hai đường bất kỳ trong hai mặt phẳng.', (s,d) => {
  const a=25+s%55,shown=d%2?180-a:a;
  return numeric(R`Hai mặt phẳng $(P),(Q)$ cắt nhau theo $d$. Tại $O\in d$, dựng $a\subset(P)$, $b\subset(Q)$ cùng vuông góc $d$. Một góc giữa hai tia của $a,b$ là $${shown}^\circ$. Tính góc giữa $(P),(Q)$ theo độ.`,a,R`Hai đường $a,b$ tạo mặt cắt vuông góc giao tuyến. Lấy góc không tù: $\min(${shown},${180-shown})^\circ=${a}^\circ$.`,scaffold('Kiểm hai đường cắt có cùng vuông góc giao tuyến không.','Góc giữa mặt phẳng lấy góc không tù của mặt cắt.',R`Ví dụ khác: góc mặt cắt $137^\circ$ có góc bù tính bởi $180^\circ-137^\circ$.`),Math.acos(Math.abs(Math.cos(shown*Math.PI/180)))*180/Math.PI);
 }),
 planePerp: nc('Điều kiện hai mặt phẳng vuông góc','Chứng minh hai mặt phẳng vuông góc bằng một đường trong mặt phẳng này vuông góc mặt phẳng kia.', R`GV yêu cầu tìm một đường chứa trong mặt phẳng thứ nhất; chứng minh đường đó vuông góc hai đường cắt nhau của mặt phẳng thứ hai. Chốt đủ bước chứa và vuông góc trước kết luận hai mặt phẳng.`, 'Dùng đường không nằm trong mặt phẳng cần chứng minh.', (s,d) => {
  const a=n(s),b=2+s%5;
  return open(R`Cho $SA\perp(ABCD)$, đáy $ABCD$ là hình chữ nhật với $AB=${a}$ cm, $AD=${b}$ cm. Chứng minh $(SAB)\perp(ABCD)$. ${d===0?'Nêu vai trò của đường $SA$.':R`Chứng minh thêm $(SAD)\perp(SAB)$.`}`,R`$SA\subset(SAB)$ và $SA\perp(ABCD)$ nên $(SAB)\perp(ABCD)$. Với kết luận thêm: $AD\perp AB$, $AD\perp SA$, do đó $AD\perp(SAB)$; $AD\subset(SAD)$ suy ra $(SAD)\perp(SAB)$.`,scaffold('Chọn một đường nằm trong mặt phẳng thứ nhất.','Chứng minh đường đó vuông góc mặt phẳng thứ hai.',R`Ví dụ khác: một bức tường chứa cạnh thẳng đứng vuông góc sàn thì mặt tường vuông góc sàn.`),['Chỉ đúng quan hệ chứa.','Chứng minh đường vuông góc mặt phẳng với đủ giả thiết; kết luận đúng.']);
 }),
 dihedral: nc('Góc nhị diện','Dựng góc phẳng của góc nhị diện, phân biệt số đo nhị diện với góc không tù giữa hai mặt phẳng.', R`GV xác định cạnh và hai nửa mặt phẳng của góc nhị diện. Trong mặt cắt vuông góc cạnh, dùng hai tia nằm đúng hai phía đã chọn; không tự thay góc tù bằng góc bù khi hỏi góc nhị diện.`, 'Tự lấy góc bù mọi khi góc phẳng nhị diện lớn hơn vuông.', (s) => {
  const angle=100+s%60;
  return open(R`Hai nửa mặt phẳng tạo góc nhị diện cạnh $d$. Mặt phẳng vuông góc $d$ cắt chúng theo hai tia $Ox,Oy$ với $\widehat{xOy}=${angle}^\circ$. Tìm số đo góc nhị diện và góc giữa hai mặt phẳng chứa hai mặt của nó.`,R`Góc nhị diện có số đo $${angle}^\circ$ theo đúng hai tia đã chọn. Góc giữa hai mặt phẳng là góc không tù $180^\circ-${angle}^\circ=${180-angle}^\circ$. Hai khái niệm không được thay thế tùy ý.`,scaffold('Xác định đề hỏi góc nhị diện hay góc giữa hai mặt phẳng.','Giữ đúng hai tia thuộc hai nửa mặt phẳng đã chọn.',R`Ví dụ khác: góc mở của một quyển sách có thể tù; góc giữa hai mặt phẳng chứa hai trang được quy ước không tù.`),['Hai số đo đúng với đúng tên gọi.','Giải thích vì sao có thể khác nhau.']);
 }),
 specialPrism: nc('Lăng trụ đứng và lăng trụ đều','Nhận biết lăng trụ đứng, lăng trụ đều, hình hộp chữ nhật qua quan hệ vuông góc và hình dạng đáy.', R`GV đưa ba mô tả thay vì chỉ hình phối cảnh. Lăng trụ đứng cần cạnh bên vuông góc đáy; lăng trụ đều cần thêm đáy là đa giác đều; lăng trụ đứng đáy hình chữ nhật là hình hộp chữ nhật.`, 'Gọi mọi lăng trụ đứng là đều; suy chiều cao bằng cạnh bên của lăng trụ xiên.', (s,d) => {
  const a=n(s),b=a+1,h=2+s%5;
  return open(R`Một lăng trụ đứng có đáy là hình chữ nhật cạnh $${a}$ cm và $${b}$ cm, cạnh bên $${h}$ cm. Nêu chiều cao, tên hình đặc biệt và giải thích vì sao nó không phải lăng trụ đều. ${d>=2?'Cần thay đổi gì ở đáy để thành lăng trụ đều tứ giác?':''}`,R`Chiều cao bằng cạnh bên, $${h}$ cm. Đây là hình hộp chữ nhật. Đáy có hai cạnh kề khác nhau nên không phải hình vuông, tức không phải đa giác đều; vì vậy không phải lăng trụ đều. Để có lăng trụ đều tứ giác, đáy phải là hình vuông.`,scaffold('Xét điều kiện cạnh bên trước, hình dạng đáy sau.','Đa giác đều cần cả cạnh bằng nhau và góc bằng nhau.',R`Ví dụ khác: một lăng trụ đứng đáy tam giác chỉ là lăng trụ đều khi tam giác đáy đều.`),['Chiều cao và tên hình đúng.','Phân biệt đứng với đều bằng điều kiện đáy.']);
 }),
 eventSet: nc('Biến cố hợp và biến cố giao','Diễn đạt biến cố hợp, biến cố giao bằng lời và xác định phần tử trong không gian mẫu hữu hạn.', R`GV cho hai tập kết quả trên thẻ; HS tô phần chỉ thuộc một tập và phần chung. Chốt hợp tương ứng ít nhất một biến cố xảy ra, giao tương ứng cả hai cùng xảy ra.`, 'Nhầm ít nhất một với đúng một; cộng số phần tử mà không bỏ trùng.', (s,d) => {
  const total=12+2*(s%7),bound=3+s%5,A=Array.from({length:total},(_,i)=>i+1).filter(x=>x%2===0),B=Array.from({length:bound},(_,i)=>i+1),isUnion=d%2===1,set=isUnion?[...new Set([...A,...B])]:A.filter(x=>B.includes(x));
  const key=set.length;
  return numeric(R`Chọn đều một thẻ trong $1,2,\ldots,${total}$. $A$: số chẵn; $B$: số không vượt quá $${bound}$. Tìm số phần tử của $${isUnion?R`A\cup B`:R`A\cap B`}$; liệt kê tập trong vở.`,key,R`Tập cần tìm là $\{${set.join(';')}\}$, có $${key}$ phần tử. ${isUnion?'Hợp chứa phần tử thuộc ít nhất một tập, không đếm trùng.':'Giao chỉ chứa phần tử cùng thuộc cả hai tập.'}`,scaffold('Liệt kê hai tập trước khi xét phép toán.','Giao lấy phần chung; hợp lấy tất cả nhưng bỏ trùng.',R`Ví dụ khác: với $A=\{1,3\}$, $B=\{3,5\}$, phần tử $3$ thuộc cả hai tập.`),Array.from({length:total},(_,i)=>i+1).filter(x=>isUnion?(x%2===0||x<=bound):(x%2===0&&x<=bound)).length);
 }),
 independence: nc('Biến cố độc lập','Kiểm tra tính độc lập qua xác suất giao, phân biệt độc lập với xung khắc.', R`GV phân biệt hai mô hình: hai phép thử độc lập và hai biến cố không thể đồng thời xảy ra. Với xác suất dương, xung khắc không phải độc lập; kiểm bằng đẳng thức xác suất giao bằng tích.`, 'Đồng nhất độc lập với không giao nhau.', (s) => {
  const a=2+s%5,b=8+s%7,total=a+b;
  return open(R`Gieo một đồng xu cân đối và chọn độc lập một thẻ trong $1,\ldots,${total}$. $A$: xu ngửa; $B$: số trên thẻ không quá $${a}$. Tính $P(A),P(B),P(A\cap B)$, kiểm tra độc lập. Có thể gọi $A,B$ là xung khắc không?`,R`$P(A)=1/2$, $P(B)=${frac(a,total)}$. Có $${a}$ kết quả thuận lợi cho giao trong $${2*total}$ cặp, nên $P(A\cap B)=${frac(a,2*total)}=P(A)P(B)$. Chúng độc lập, không xung khắc vì giao có xác suất dương.`,scaffold('Không gian mẫu gồm các cặp kết quả xu và thẻ.','Đếm số cặp cùng thỏa hai điều kiện.',R`Ví dụ khác: hai lần gieo xu độc lập vẫn có thể cùng ngửa; độc lập không có nghĩa là loại trừ nhau.`),['Ba xác suất đúng.','Kiểm đẳng thức độc lập; phân biệt xung khắc bằng giao.']);
 }),
 disjointSum: nc('Cộng xác suất cho biến cố xung khắc','Nhận biết các trường hợp xung khắc và cộng xác suất không đếm trùng.', R`Dùng hộp bóng phân màu, mỗi lượt chỉ rút một bóng. GV hỏi vì sao hai màu khác nhau không xảy ra cùng lúc, rồi mới cộng xác suất.`, 'Cộng xác suất trước khi kiểm các biến cố có xung khắc không.', (s) => {
  const a=2+s%11,b=3+(s*3)%7,c=4+(s*5)%7,total=a+b+c;
  return numeric(R`Hộp có $${a}$ bóng đỏ, $${b}$ bóng xanh, $${c}$ bóng vàng như nhau về kích thước. Rút ngẫu nhiên một bóng. Tính xác suất bóng đỏ hoặc xanh.`,(a+b)/total,R`Hai màu xung khắc trong một lần rút. Xác suất $${frac(a,total)}+${frac(b,total)}=${frac(a+b,total)}$.`,scaffold('Mỗi lần rút được đúng một màu.','Cộng các số trường hợp thuận lợi vì hai nhóm không trùng.',R`Ví dụ khác: trong một lần gieo xúc xắc, ra mặt một và ra mặt hai là hai biến cố xung khắc.`),probability(Array.from({length:total},(_,i)=>i).filter(i=>i<a+b).length,total));
 }),
 unionProbability: nc('Cộng xác suất cho hai biến cố bất kỳ','Dùng công thức xác suất hợp và trừ phần giao được đếm hai lần.', R`GV lập bảng hai tiêu chí hoặc biểu đồ hai tập. Đếm trực tiếp rồi so với tổng số ở hai tập để thấy phần chung bị tính hai lần.`, 'Quên trừ phần giao; trừ hai lần phần giao.', (s) => {
  const both=2+s%5,onlyA=3+(s*2)%7,onlyB=4+(s*3)%7,neither=5+s%4,total=both+onlyA+onlyB+neither;
  return numeric(R`Một nhóm giả định có $${total}$ học sinh: $${onlyA}$ em chỉ thích cờ vua, $${onlyB}$ em chỉ thích bóng bàn, $${both}$ em thích cả hai, còn lại không thích môn nào. Chọn đều một em. Tính xác suất em đó thích ít nhất một trong hai môn.`,(both+onlyA+onlyB)/total,R`$P(A\cup B)=P(A)+P(B)-P(A\cap B)=(${onlyA+both}+${onlyB+both}-${both})/${total}=${frac(both+onlyA+onlyB,total)}$.`,scaffold('Chia thành bốn nhóm không trùng nhau.','Ít nhất một gồm ba nhóm, không gồm nhóm không thích môn nào.',R`Ví dụ khác: phần giao nằm trong cả hai hình tròn; khi cộng hai tập cần bớt một lần phần này.`),1-neither/total);
 }),
 indProduct: nc('Nhân xác suất của biến cố độc lập','Tính xác suất đồng thời xảy ra bằng quy tắc nhân trong mô hình độc lập.', R`GV vẽ cây hai bước: mỗi nhánh bước hai có cùng xác suất nhờ giả thiết độc lập. HS nhân theo nhánh, phân biệt với cộng các nhánh loại trừ nhau.`, 'Dùng quy tắc nhân khi không có độc lập; cộng thay nhân cho cả hai cùng xảy ra.', (s) => {
  const a=2+s%4,b=7+s%5,c=2+(s*3)%4,e=8+(s*2)%5;
  return numeric(R`Hai hộp độc lập: hộp I có $${a}$ thẻ đỏ trong $${b}$ thẻ, hộp II có $${c}$ thẻ đỏ trong $${e}$ thẻ. Rút ngẫu nhiên một thẻ từ mỗi hộp. Tính xác suất cả hai đều đỏ.`,a*c/(b*e),R`Hai phép rút độc lập nên xác suất $${frac(a,b)}\cdot${frac(c,e)}=${frac(a*c,b*e)}$.`,scaffold('Xác định mỗi phép thử và xác suất đỏ của nó.','Cả hai cùng đỏ tương ứng một nhánh hai bước.',R`Ví dụ khác: hai lần gieo xúc xắc riêng biệt, xác suất cả hai ra một mặt cố định được tính bằng tích hai xác suất.`),Array.from({length:b},(_,i)=>Array.from({length:e},(_,j)=>i<a&&j<c?1:0)).flat().reduce((x,y)=>x+y,0)/(b*e));
 }),
 atLeastOne: nc('Biến cố đối trong bài toán độc lập','Tính xác suất ít nhất một thành công bằng biến cố đối không có thành công.', R`GV yêu cầu đọc từ ít nhất trước khi chọn công thức. Dùng cây hai bước để xác định biến cố đối; chỉ nhân xác suất thất bại khi hai phép thử độc lập.`, 'Nhầm ít nhất một với đúng một; lấy đối sai.', (s) => {
  const a=2+s%5,b=10+s%3,c=3+(s*3)%5;
  return numeric(R`Hai phép thử độc lập có xác suất thành công lần lượt $${frac(a,b)}$ và $${frac(c,b)}$. Tính xác suất có ít nhất một lần thành công.`,1-(b-a)*(b-c)/(b*b),R`Biến cố đối là cả hai thất bại. Kết quả $1-(1-${frac(a,b)})(1-${frac(c,b)})=${frac(b*b-(b-a)*(b-c),b*b)}$.`,scaffold('Viết biến cố đối của ít nhất một.','Tính xác suất cả hai thất bại trước.',R`Ví dụ khác: đối của ít nhất một bóng đèn sáng là không bóng nào sáng.`),a/b+c/b-a*c/(b*b));
 }),
 exactlyOne: nc('Đúng một biến cố xảy ra','Tách biến cố đúng một thành hai trường hợp xung khắc rồi nhân và cộng đúng.', R`GV viết hai nhánh: thành công–thất bại và thất bại–thành công. Chốt hai nhánh xung khắc; không bao gồm cùng thành công.`, 'Dùng công thức ít nhất một khi đề hỏi đúng một.', (s) => {
  const a=2+s%5,b=10+s%3,c=3+(s*3)%5;
  return numeric(R`Hai học sinh làm độc lập một nhiệm vụ; mô hình cho xác suất hoàn thành lần lượt $${frac(a,b)}$ và $${frac(c,b)}$. Tính xác suất đúng một em hoàn thành.`,(a*(b-c)+(b-a)*c)/(b*b),R`Hai trường hợp xung khắc có xác suất $${frac(a,b)}(1-${frac(c,b)})$ và $(1-${frac(a,b)})${frac(c,b)}$. Tổng bằng $${frac(a*(b-c)+(b-a)*c,b*b)}$.`,scaffold('Liệt kê hai trường hợp đúng một.','Mỗi trường hợp là giao của một thành công và một thất bại.',R`Ví dụ khác: với hai đèn, đúng một sáng gồm sáng–tắt hoặc tắt–sáng, không gồm sáng–sáng.`),a/b+c/b-2*a*c/(b*b));
 }),
 derivativeDefinition: nc('Đạo hàm tại một điểm','Dùng giới hạn tỉ số số gia để tính đạo hàm của hàm bậc hai tại một điểm.', R`GV viết số gia đầu vào và đầu ra, rút gọn khi số gia khác không rồi mới lấy giới hạn. Phân biệt tốc độ trung bình trên một đoạn với tốc độ tức thời tại điểm.`, 'Thế số gia bằng không trước khi rút gọn; lấy đạo hàm bằng giá trị hàm.', (s,d) => {
  const a=1+s%4,b=2+s%5,x=2+s%7,c=d+1,key=2*a*x+b;
  derivativeCheck(t=>a*t*t+b*t+c,x,key);
  return numeric(R`Cho $f(x)=${a}x^2+${b}x+${c}$. Dùng định nghĩa giới hạn để tìm $f'(${x})$. Nhập giá trị; trình bày tỉ số số gia trong vở.`,key,R`$[f(${x}+h)-f(${x})]/h=${2*a*x+b}+${a}h$ với $h\ne0$. Cho $h\to0$ được $f'(${x})=${key}$.`,scaffold('Bắt đầu từ hiệu giá trị hàm ở hai đầu.','Chia hiệu cho số gia sau khi khai triển.',R`Ví dụ khác: với $g(t)=t^2$ tại $t=37$, hiệu có nhân tử $h$ nên rút gọn trước khi lấy giới hạn.`),((a*(x+1)**2+b*(x+1)+c)-(a*(x-1)**2+b*(x-1)+c))/2);
 }),
 derivativeMeaning: nc('Ý nghĩa vật lý và hình học của đạo hàm','Tính đạo hàm trên một khoảng, vận dụng cho vận tốc tức thời và hệ số góc tiếp tuyến.', R`GV dùng cùng một đồ thị để đọc độ dốc tiếp tuyến, rồi đổi ngữ cảnh sang quãng đường theo thời gian. Chốt đơn vị vận tốc và phương trình tiếp tuyến đi qua đúng điểm trên đồ thị.`, 'Nhầm vận tốc với quãng đường; dùng hệ số góc nhưng bỏ điểm tiếp xúc.', (s,d) => {
  const a=1+s%4,b=2+s%5,t=2+s%6,c=d+1,y=a*t*t+b*t+c,slope=2*a*t+b;derivativeCheck(x=>a*x*x+b*x+c,t,slope);
  return open(R`Hàm $f(x)=${a}x^2+${b}x+${c}$. Tìm $f'(x)$ và phương trình tiếp tuyến tại $x=${t}$. Nếu $s(t)=${a}t^2+${b}t+${c}$ là vị trí (m), thời gian tính bằng giây, vận tốc tại $t=${t}$ s bằng bao nhiêu?`,R`$f'(x)=${2*a}x+${b}$ trên $\mathbb R$. Điểm tiếp xúc $(${t};${y})$, hệ số góc $${slope}$. Tiếp tuyến $y-${y}=${slope}(x-${t})$. Vận tốc $s'(${t})=${slope}$ m/s.`,scaffold('Phân biệt giá trị hàm và giá trị đạo hàm.','Tìm cả điểm tiếp xúc lẫn hệ số góc.',R`Ví dụ khác: tiếp tuyến tại $x=37$ có dạng $y-f(37)=f'(37)(x-37)$.`),['Đạo hàm trên khoảng đúng.','Tiếp tuyến đúng cả điểm và hệ số góc.','Vận tốc đúng kèm đơn vị.']);
 }),
 polyRationalDerivative: nc('Đạo hàm đa thức và phân thức','Vận dụng quy tắc tổng, tích, thương để tìm đạo hàm đa thức và phân thức trên miền xác định.', R`GV làm mẫu đạo hàm từng hạng của đa thức, sau đó giữ nguyên khung tử của quy tắc thương trước khi rút gọn. HS nêu miền xác định của phân thức và kiểm dấu của tử.`, 'Đạo hàm thương bằng thương đạo hàm; bỏ bình phương mẫu.', (s) => {
  const a=2+s%6,b=1+s%5,c=2+(s*3)%5,constant=a*c-b;
  derivativeCheck(x=>(a*x+b)/(x+c),1,constant/(1+c)**2);
  return open(R`Tìm đạo hàm của $f(x)=(x+${a})(x^2+${b})$ và $g(x)=(${a}x+${b})/(x+${c})$. Với $f$, đối chiếu quy tắc tích với cách khai triển rồi lấy đạo hàm. Ghi miền xác định của $g$ và tính $g'(1)$.`,R`$f'(x)=(x^2+${b})+(x+${a})2x=3x^2+${2*a}x+${b}$. Với $x\ne-${c}$, $g'(x)=[${a}(x+${c})-(${a}x+${b})]/(x+${c})^2=${constant}/(x+${c})^2$. Suy ra $g'(1)=${frac(constant,(1+c)**2)}$.`,scaffold('Làm đa thức từng hạng; phân thức dùng quy tắc thương.','Viết tử dưới dạng đạo hàm tử nhân mẫu trừ tử nhân đạo hàm mẫu.',R`Ví dụ khác: với $u/v$, đặt khung $(u'v-uv')/v^2$ trước khi thay biểu thức cụ thể.`),['Đạo hàm đa thức đúng.','Quy tắc thương, miền và giá trị tại điểm đúng.']);
 }),
 chainRootDerivative: nc('Đạo hàm hàm hợp và hàm chứa căn','Tính đạo hàm hàm hợp, giữ thừa số đạo hàm bên trong và điều kiện của căn.', R`GV khoanh hàm trong, đặt ký hiệu tạm rồi dùng quy tắc dây chuyền. Với căn bậc hai, phân biệt miền xác định và miền có công thức đạo hàm hữu hạn; không dùng công thức tại điểm đối số bằng không.`, 'Quên nhân đạo hàm bên trong; dùng công thức đạo hàm căn ngay tại điểm biên.', (s) => {
  const a=2+s%5,b=1+s%4,p=2+s%3;derivativeCheck(x=>(a*x+b)**p,1,p*a*(a+b)**(p-1));derivativeCheck(x=>Math.sqrt(a*x+b),1,a/(2*Math.sqrt(a+b)));
  return open(R`Tìm đạo hàm $f(x)=(${a}x+${b})^{${p}}$ và $g(x)=\sqrt{${a}x+${b}}$. Nêu miền dùng công thức đạo hàm của $g$.`,R`$f'(x)=${p*a}(${a}x+${b})^{${p-1}}$. Với $x>-${b}/${a}$, $g'(x)=${a}/(2\sqrt{${a}x+${b}})$. Hàm $g$ xác định tại biên nhưng công thức đạo hàm hữu hạn này không áp dụng ở đó.`,scaffold('Xác định hàm ngoài và hàm trong.','Tính đạo hàm hàm trong trước rồi nhân vào đạo hàm hàm ngoài.',R`Ví dụ khác: đạo hàm $(37x+1)^2$ gồm đạo hàm bình phương nhân thêm đạo hàm của $37x+1$.`),['Hai đạo hàm đúng thừa số hàm trong.','Miền đạo hàm căn dùng bất đẳng thức nghiêm.']);
 }),
 trigExpLogDerivative: nc('Đạo hàm lượng giác, mũ và lôgarit','Tính đạo hàm hàm lượng giác, hàm số mũ và hàm lôgarit, kể cả hàm hợp tuyến tính.', R`GV đặt bốn công thức cạnh nhau: sin, cos, mũ cơ số tự nhiên hoặc cơ số bất kỳ, lôgarit. Nhấn dấu âm của cos, thừa số lôgarit cơ số và đạo hàm đối số; góc dùng radian.`, 'Quên dấu âm của cos; quên lôgarit cơ số hoặc đạo hàm bên trong.', (s) => {
  const a=2+s%4,k=1+s%5,b=1+s%4;derivativeCheck(x=>Math.sin(k*x)+Math.cos(k*x),0.4,k*Math.cos(k*0.4)-k*Math.sin(k*0.4));derivativeCheck(x=>a**(k*x),0.2,k*Math.log(a)*a**(k*0.2));derivativeCheck(x=>Math.log(k*x+b)/Math.log(a),1,k/((k+b)*Math.log(a)));
  derivativeCheck(x=>Math.tan(k*x)+1/Math.tan(k*x),0.2,k/Math.cos(k*0.2)**2-k/Math.sin(k*0.2)**2);
  return open(R`Tính đạo hàm: $f(x)=\sin(${k}x)+\cos(${k}x)$; $p(x)=\tan(${k}x)+\cot(${k}x)$; $g(x)=${a}^{${k}x}$; $h(x)=\log_${a}(${k}x+${b})$. Góc tính bằng radian. Ghi điều kiện của $p,h$.`,R`$f'(x)=${k}\cos(${k}x)-${k}\sin(${k}x)$; $p'(x)=${k}/\cos^2(${k}x)-${k}/\sin^2(${k}x)$ khi $\sin(${k}x)\cos(${k}x)\ne0$. $g'(x)=${k}\ln ${a}\cdot${a}^{${k}x}$; $h'(x)=${k}/[(${k}x+${b})\ln ${a}]$ với $x>-${b}/${k}$.`,scaffold('Nhận diện công thức theo từng hàm ngoài.','Đặt thừa số đạo hàm bên trong ra riêng để tránh bỏ sót.',R`Ví dụ khác: đạo hàm $e^{37x}$ gồm $e^{37x}$ nhân đạo hàm của $37x$.`),['Đạo hàm sin, cos, tan, cot đúng dấu và điều kiện.','Đạo hàm mũ và lôgarit đúng thừa số cơ số/hàm trong.','Điều kiện lôgarit đúng.']);
 }),
 derivativePractice: nc('Luyện chọn quy tắc đạo hàm','Kết hợp quy tắc tích và hàm hợp, giải thích lựa chọn quy tắc thay vì chỉ ghi kết quả.', R`GV yêu cầu HS đánh dấu phép toán ngoài cùng trước khi tính. Dùng một lỗi minh họa bỏ mất một số hạng của quy tắc tích rồi cho HS sửa bằng cách kiểm số hạng.`, 'Áp dụng quy tắc tích như đạo hàm từng thừa số rồi nhân.', (s) => {
  const a=2+s%5,b=1+s%6,k=1+s%4;derivativeCheck(x=>(x*x+a)*Math.exp(k*x),0.2,Math.exp(k*0.2)*(0.4+k*(0.04+a)));
  return open(R`Tìm đạo hàm $f(x)=(x^2+${a})e^{${k}x}$ và $g(x)=\ln(x^2+${b})$. Nêu quy tắc dùng ở mỗi bước và miền xác định.`,R`$f'(x)=e^{${k}x}[2x+${k}(x^2+${a})]$ từ quy tắc tích và hàm hợp. $g'(x)=2x/(x^2+${b})$. Vì $${b}>0$, hai hàm đều xác định và có đạo hàm trên $\mathbb R$.`,scaffold('Tìm phép toán ngoài cùng: tích hoặc hàm hợp.','Quy tắc tích tạo hai số hạng, quy tắc hàm hợp tạo thừa số.',R`Ví dụ khác: $(uv)'=u'v+uv'$, không phải $u'v'$.`),['Đạo hàm tích đủ hai số hạng.','Đạo hàm lôgarit hàm hợp và miền đúng.']);
 }),
 distancePoint: nc('Khoảng cách từ điểm đến đường và mặt phẳng','Xác định chân vuông góc, tính khoảng cách từ điểm đến đường và mặt phẳng bằng tam giác vuông.', R`GV yêu cầu vẽ đoạn vuông góc đúng đối tượng đích trước khi tính. Dùng hình chóp có đường cao cho sẵn; khoảng cách không phải đoạn nối ngắn nhất được đo bằng mắt.`, 'Lấy đường xiên thay đường vuông góc; bỏ chứng minh chân thuộc đối tượng.', (s) => {
  const a=3+s%7,h=4+(s*3)%11;
  return open(R`Cho $SA\perp(ABCD)$, đáy hình chữ nhật, $AB=${a}$ cm, $SA=${h}$ cm. Tính $d(S,(ABCD))$ và $d(S,AB)$. Nếu $H$ là chân đường vuông góc từ $A$ tới $SB$, tính $AH$.`,R`Vì $SA\perp(ABCD)$ và $A\in AB$, hai khoảng cách đầu đều bằng $SA=${h}$ cm. Trong tam giác vuông $SAB$, $SB=\sqrt{${a*a+h*h}}$; so hai cách tính diện tích: $AH=SA\cdot AB/SB=${a*h}/\sqrt{${a*a+h*h}}$ cm.`,scaffold('Xác định chân vuông góc cho từng đối tượng.','Dùng hai cách tính diện tích tam giác vuông để tìm đường cao xuống cạnh huyền.',R`Ví dụ khác: tam giác vuông có hai cạnh góc vuông $3,4$ thì đường cao xuống cạnh huyền được lập từ $3\cdot4=5h$.`),['Hai khoảng cách đầu và lý do đúng.','Lập được công thức đường cao, kết quả và đơn vị đúng.']);
 }),
 distanceParallel: nc('Khoảng cách giữa các đối tượng song song','Chuyển khoảng cách đường–mặt phẳng hoặc hai mặt phẳng song song về một đoạn vuông góc.', R`Dùng hình hộp chữ nhật, GV đánh dấu một điểm trên đối tượng thứ nhất và chân chiếu trên đối tượng thứ hai. Kiểm song song trước khi dùng khoảng cách không đổi.`, 'Chọn điểm không thuộc đối tượng; lấy đường chéo thay đoạn vuông góc.', (s) => {
  const a=n(s),b=3+s%7,h=4+s%6;
  return open(R`Hình hộp chữ nhật $ABCD.A'B'C'D'$ có $AB=${a}$ cm, $AD=${b}$ cm, $AA'=${h}$ cm. Tính $d(AB,CD)$, $d(A'B',(ABCD))$, $d((ABB'A'),(DCC'D'))$.`,R`$AB\parallel CD$ và $AD\perp AB,CD$, nên khoảng cách thứ nhất $AD=${b}$ cm. Đường $A'B'$ song song đáy; đoạn $A'A$ vuông góc đáy cho khoảng cách $${h}$ cm. Hai mặt bên song song, $AD$ vuông góc cả hai nên khoảng cách $${b}$ cm.`,scaffold('Xác định cặp đối tượng song song rồi chọn điểm thuận lợi.','Tìm cạnh hộp vuông góc nối hai đối tượng.',R`Ví dụ khác: khoảng cách giữa hai mặt sàn song song được đo theo một đoạn thẳng đứng vuông góc, không theo cầu thang xiên.`),['Ba khoảng cách đúng.','Mỗi kết quả có đoạn vuông góc và quan hệ thuộc tương ứng.']);
 }),
 distanceSkew: nc('Khoảng cách giữa hai đường chéo nhau','Nhận diện đoạn vuông góc chung và tính khoảng cách giữa hai đường chéo nhau.', R`GV kiểm ba điều của đoạn vuông góc chung: hai đầu thuộc hai đường, vuông góc đường thứ nhất, vuông góc đường thứ hai. Không dùng khoảng cách giữa hai điểm tùy chọn.`, 'Một đoạn chỉ vuông góc một đường chưa phải vuông góc chung.', (s,d) => {
  const a=n(s),b=3+s%7,h=4+s%6;
  return open(R`Trong hình hộp chữ nhật $ABCD.A'B'C'D'$, $AB=${a}$ cm, $AD=${b}$ cm, $AA'=${h}$ cm. Chứng minh $BC$ là đoạn vuông góc chung của $AB$ và $CC'$, rồi tính $d(AB,CC')$. ${d>=2?"Tính thêm $d(AB,C'D')$.":'' }`,R`$B\in AB$, $C\in CC'$. $BC\perp AB$ trong đáy và $BC\perp CC'$ vì cạnh đứng vuông góc đáy. Hai đường $AB,CC'$ chéo nhau; khoảng cách là $BC=${b}$ cm. Với $AB,C'D'$: chúng song song; đoạn $AD'$ vuông góc cả hai nên khoảng cách $\sqrt{${b*b+h*h}}$ cm.`,scaffold('Kiểm vị trí hai đầu mút trước khi kiểm vuông góc.','Dùng cạnh đáy vuông góc cạnh ngang và cạnh đứng.',R`Ví dụ khác: đoạn nối hai đường chỉ được dùng khi hai đầu nằm đúng trên chúng và đoạn cùng vuông góc cả hai.`),['Chứng minh đủ ba điều của đoạn vuông góc chung.','Phân biệt cặp chéo nhau với cặp song song; tính và đơn vị đúng.']);
 }),
 distanceCombined: nc('Luyện khoảng cách bằng diện tích','Tính khoảng cách tới mặt phẳng bằng đường cao trong một mặt cắt vuông góc phù hợp.', R`GV vẽ mặt cắt tam giác vuông có chứa đường cao cần tìm. HS chứng minh đường cao đó vuông góc thêm một đường của mặt phẳng đích, rồi dùng diện tích để tính.`, 'Tính đường cao trong một tam giác nhưng chưa chứng minh vuông góc mặt phẳng.', (s) => {
  const a=3+s%8,h=4+(s*3)%7;
  return open(R`Cho $SA\perp(ABCD)$, đáy hình chữ nhật, $AB=${a}$ cm, $SA=${h}$ cm. Gọi $H$ là chân đường vuông góc từ $A$ tới $SB$. Chứng minh $AH\perp(SBC)$ và tính $d(A,(SBC))$.`,R`$BC\perp AB$ và $BC\perp SA$ nên $BC\perp(SAB)$, suy ra $BC\perp AH$. Kết hợp $AH\perp SB$ và $BC,SB$ cắt nhau trong $(SBC)$, được $AH\perp(SBC)$. Khoảng cách $AH=SA\cdot AB/SB=${a*h}/\sqrt{${a*a+h*h}}$ cm.`,scaffold('Chứng minh đường cao vuông góc thêm một đường trong mặt phẳng đích.','Dùng cạnh đáy vuông góc cả đường cao và cạnh đáy còn lại.',R`Ví dụ khác: một đoạn vuông góc hai đường cắt nhau trong mặt phẳng sẽ vuông góc cả mặt phẳng.`),['Chứng minh vuông góc mặt phẳng trước khi gọi khoảng cách.','Tính độ dài bằng diện tích, giữ đơn vị đúng.']);
 }),
 volumePyramid: nc('Thể tích khối chóp','Tính thể tích khối chóp bằng diện tích đáy và chiều cao vuông góc.', R`GV xác định đáy và chân đường cao trên mô hình. Chốt hệ số một phần ba; cạnh bên chỉ là chiều cao khi có quan hệ vuông góc phù hợp.`, 'Quên hệ số một phần ba; lấy cạnh bên xiên làm chiều cao.', (s) => {
  const a=3+s%8,b=2+(s*3)%7,h=3*(2+s%5),key=a*b*h/3;
  return numeric(R`Khối chóp $S.ABCD$ có đáy hình chữ nhật $AB=${a}$ cm, $AD=${b}$ cm, $SA\perp(ABCD)$, $SA=${h}$ cm. Tính thể tích theo cm$^3$.`,key,R`Diện tích đáy $S_{ABCD}=${a*b}$ cm$^2$, chiều cao $SA=${h}$ cm. $V=\frac13 S_{ABCD}\cdot SA=${key}$ cm$^3$.`,scaffold('Xác định diện tích đáy và đoạn vuông góc đáy.','Viết công thức thể tích có hệ số một phần ba.',R`Ví dụ khác: với đáy diện tích $37$ và cao $6$, thay vào $V=S_{\text{đáy}}h/3$ trước khi tính.`),a*b*(h/3));
 }),
 volumePrism: nc('Thể tích lăng trụ và khối hộp','Tính thể tích lăng trụ bằng diện tích đáy nhân chiều cao, phân biệt với công thức khối chóp.', R`GV dùng một lăng trụ đứng đáy tam giác vuông và một hình hộp chữ nhật. Chốt không có hệ số một phần ba; với lăng trụ xiên, chiều cao là khoảng cách hai đáy, không phải cạnh bên.`, 'Dùng hệ số một phần ba cho lăng trụ; quên chia đôi diện tích tam giác đáy.', (s,d) => {
  const a=2+s%8,b=2*(2+(s*3)%7),h=3+s%7,tri=d%2===1,key=a*b*h/(tri?2:1);
  return numeric(tri?R`Lăng trụ đứng đáy tam giác vuông có hai cạnh góc vuông $${a}$ cm, $${b}$ cm; cạnh bên $${h}$ cm. Tính thể tích theo cm$^3$.`:R`Hình hộp chữ nhật có ba kích thước $${a}$ cm, $${b}$ cm, $${h}$ cm. Tính thể tích theo cm$^3$.`,key,R`Diện tích đáy $${tri?R`\frac12\cdot`:''}${a}\cdot${b}=${a*b/(tri?2:1)}$ cm$^2$. Chiều cao $${h}$ cm, nên $V=S_{\text{đáy}}h=${key}$ cm$^3$.`,scaffold('Tính diện tích đúng hình dạng đáy.','Lăng trụ đứng có chiều cao bằng cạnh bên.',R`Ví dụ khác: đáy tam giác vuông diện tích $ab/2$, thể tích lăng trụ là $(ab/2)h$.`),Array.from({length:h},()=>a*b/(tri?2:1)).reduce((x,y)=>x+y,0));
 }),
};
Object.assign(bank, hk);

const extensionQuestions = {
 lineAngle: s => {const angle=100+s%60;return challenge(R`Hai đường $a,b$ có hai đường song song qua $O$ tạo góc $${angle}^\circ$. Một em kết luận góc giữa $a,b$ là $${angle}^\circ$ và vì vậy chúng không thể vuông góc. Phần nào đúng, phần nào sai?`,R`Góc giữa hai đường là $${180-angle}^\circ$, nên số đo được nêu là sai. Kết luận không vuông góc đúng vì góc này khác $90^\circ$, nhưng phải dựa trên số đo đúng.`,'Tách tính đúng của kết luận khỏi tính đúng của lập luận.');},
 planeAngle: s => {const angle=105+s%60;return challenge(R`Hai mặt phẳng cắt nhau theo $d$. Tại cùng điểm $O\in d$, hai đường nằm trong hai mặt phẳng đều vuông góc $d$ và tạo một góc $${angle}^\circ$. Hai em đề xuất góc giữa hai mặt phẳng là $${angle}^\circ$ và $${180-angle}^\circ$. Chọn kết luận đúng, giải thích; nếu bỏ điều kiện vuông góc $d$ thì cách đo có còn hợp lệ không?`,R`Theo định nghĩa lấy góc không tù, nên góc đúng $${180-angle}^\circ$. Hai đường phải cùng vuông góc giao tuyến tại một điểm; nếu chọn tùy ý thì góc của chúng không xác định góc giữa hai mặt phẳng.`,'Kiểm điều kiện của mặt cắt trước khi chọn góc không tù.');},
 derivativeDefinition: s => {const a=n(s);return challenge(R`Dùng định nghĩa kiểm tra hàm $f(x)=|x-${a}|$ có đạo hàm tại $x=${a}$ không. Không suy từ việc hàm liên tục tại điểm đó.`,R`Tỉ số số gia là $|h|/h$, bằng $1$ khi $h>0$ và $-1$ khi $h<0$. Hai giới hạn một phía khác nhau nên không có đạo hàm tại $${a}$, dù hàm liên tục.`,'Xét riêng số gia dương và âm.');},
 derivativeMeaning: s => {const a=2+s%7,k=1+s%5;return challenge(R`Cho $f(x)=x^2+${a}x$. Tìm điểm trên đồ thị có tiếp tuyến song song đường $y=${2*k+a}x+37$ và viết tiếp tuyến.`,R`Cần $f'(x)=2x+${a}=${2*k+a}$, nên $x=${k}$. Điểm $(${k};${k*k+a*k})$, tiếp tuyến $y-${k*k+a*k}=${2*k+a}(x-${k})$.`,'Tiếp tuyến song song khi hệ số góc bằng nhau; sau đó tìm điểm tiếp xúc.');},
 polyRationalDerivative: s => {const a=2+s%6,c=1+s%5;return challenge(R`Tìm $m$ để đạo hàm của $g(x)=(${a}x+m)/(x+${c})$ bằng không tại mọi điểm xác định. Hàm có trở thành hàm xác định trên toàn trục không?`,R`$g'(x)=(${a*c}-m)/(x+${c})^2$. Cần $m=${a*c}$. Khi đó giá trị hàm bằng $${a}$ nhưng miền gốc vẫn loại $x=-${c}$; phép rút gọn không tự bổ sung điểm bị loại.`,'Cho tử của đạo hàm bằng không và giữ miền ban đầu.');},
 chainRootDerivative: s => {const a=2+s%5;return challenge(R`So sánh $f(x)=\sqrt{x^2+${a}}$ và $g(x)=\sqrt{x^2}$ về đạo hàm tại $0$.`,R`$f'(x)=x/\sqrt{x^2+${a}}$ nên $f'(0)=0$. $g(x)=|x|$, không có đạo hàm tại $0$ vì hai giới hạn số gia là $1$ và $-1$.`,'Căn của bình phương là trị tuyệt đối; không rút gọn thành biến trên cả trục.');},
 trigExpLogDerivative: s => {const a=2+s%5,k=1+s%4;return challenge(R`Một em tính đạo hàm $f(x)=\log_${a}(e^{${k}x})$ bằng $1/x$. Hãy dùng hai cách để tìm đạo hàm đúng và chỉ ra lỗi.`,R`Rút gọn $f(x)=${k}x/\ln ${a}$ nên $f'(x)=${k}/\ln ${a}$. Hoặc dùng công thức hàm hợp: $(${k}e^{${k}x})/(e^{${k}x}\ln ${a})$. Lỗi là dùng công thức $\ln x$ mà bỏ cả cơ số và đối số hợp.`,'Thử đổi lôgarit về cơ số tự nhiên trước khi lấy đạo hàm.');},
 derivativePractice: s => {const a=2+s%6;return challenge(R`Tìm $m$ để tiếp tuyến của $f(x)=(x^2+m)e^x$ tại $x=0$ có hệ số góc $${a}$. Viết phương trình tiếp tuyến đó.`,R`$f'(x)=e^x(x^2+2x+m)$ nên $f'(0)=m=${a}$. Điểm tiếp xúc $(0;${a})$, tiếp tuyến $y=${a}x+${a}$.`,'Tính đạo hàm bằng quy tắc tích rồi mới thay điểm.');},
 distancePoint: s => {const a=3+s%7,h=4+s%5;return challenge(R`Tam giác $SAB$ vuông tại $A$ có $SA=${h}$ cm, $AB=${a}$ cm. Chân đường vuông góc từ $A$ xuống $SB$ là $H$. So sánh $AH$ với cả $SA$ và $AB$ bằng công thức, không đo hình.`,R`$AH=SA\cdot AB/SB=${a*h}/\sqrt{${a*a+h*h}}$. Vì $SB>AB$ và $SB>SA$, nên $AH<SA$ và $AH<AB$.`,'Dùng độ dài cạnh huyền lớn hơn từng cạnh góc vuông.');},
 distanceParallel: s => {const a=3+s%7,h=4+s%5;return challenge(R`Trong hình hộp chữ nhật $ABCD.A'B'C'D'$, $AD=${a}$ cm, $AA'=${h}$ cm. Một em dùng $AD'$ làm khoảng cách giữa $(ABB'A')$ và $(DCC'D')$. Hãy chỉ ra sai lầm và nêu khoảng cách đúng.`,R`$AD'$ là đường xiên, không vuông góc mặt bên đích. Đoạn $AD$ vuông góc cả hai mặt bên song song, nên khoảng cách $${a}$ cm; $AD'=\sqrt{${a*a+h*h}}>${a}$.`,'Kiểm quan hệ vuông góc trước khi dùng độ dài đoạn nối.');},
 distanceSkew: s => {const a=3+s%7,h=4+s%5;return challenge(R`Trong hình hộp chữ nhật có $AD=${a}$ cm, $AA'=${h}$ cm, so sánh $d(AB,CC')$ và $d(AB,C'D')$. Vì sao cùng chọn một đường $AB$ nhưng hai công thức khác nhau?`,R`Cặp $AB,CC'$ chéo nhau, đoạn vuông góc chung $BC$ cho khoảng cách $${a}$ cm. Cặp $AB,C'D'$ song song; $AD'$ vuông góc cả hai, cho khoảng cách $\sqrt{${a*a+h*h}}$ cm. Vị trí tương đối và đoạn vuông góc hợp lệ khác nhau.`,'Xét vị trí tương đối từng cặp rồi xác định đoạn vuông góc.');},
 distanceCombined: s => {const a=3+s%7,h=4+s%5;return challenge(R`Cho $SA\perp(ABCD)$, đáy chữ nhật, $AB=${a}$ cm, $SA=${h}$ cm. So sánh $d(A,(SBC))$ với $d(D,(SBC))$ mà không tính hai lần.`,R`$AD\parallel BC\subset(SBC)$ và $AD$ không nằm trong $(SBC)$, nên $AD\parallel(SBC)$. Mọi điểm trên $AD$ có cùng khoảng cách tới mặt phẳng; hai khoảng cách bằng nhau, cùng bằng $${a*h}/\sqrt{${a*a+h*h}}$ cm.`,'Tìm đường song song mặt phẳng đi qua hai điểm cần so sánh.');},
 exEq: s => {const a=2+s%4,k=1+s%3;return challenge(R`Giải $${a}^{2x}-(${a**k}+${a**(k+1)})${a}^x+${a**(2*k+1)}=0$ bằng đặt ẩn phụ; giải thích vì sao chỉ nhận ẩn phụ dương.`,R`Đặt $t=${a}^x>0$. Phương trình $(t-${a**k})(t-${a**(k+1)})=0$. Cả hai giá trị đều dương, cho $x=${k}$ hoặc $x=${k+1}$.`,'Đặt một lũy thừa làm ẩn phụ, rồi phân tích tam thức.');},
 lgEq: s => {const a=2+s%4,k=n(s);return challenge(R`Giải $\log_${a}(x-${k})+\log_${a}(x-${k})=2$. Một lời giải nhận $x=${k}- ${a}$ có hợp lệ không?`,R`Điều kiện $x>${k}$. Phương trình tương đương $\log_${a}(x-${k})=1$, cho $x=${k+a}$. Nghiệm $${k-a}$ làm đối số âm nên bị loại.`,'Viết điều kiện trước khi biến đổi tổng hai lôgarit.');},
 exDomain: s => {const a=2+s%5,k=n(s);return challenge(R`So sánh tính đơn điệu của $f(x)=${a}^{x-${k}}$ và $g(x)=${a}^{${k}-x}$. Giải thích vì sao cùng cơ số nhưng chiều biến thiên khác nhau.`,R`$f$ đồng biến. $g(x)=(1/${a})^{x-${k}}$ nên nghịch biến. Dấu của hệ số biến trong số mũ phải được xét, không chỉ cơ số viết ban đầu.`,'Viết hàm thứ hai dưới dạng cơ số nghịch đảo.');},
 exGraph: s => {const a=2+s%4,k=n(s);return challenge(R`Hai đồ thị $y=${a}^{x-${k}}$ và $y=${a}^{${k}-x}$ đối xứng qua đường thẳng nào? Tìm giao điểm bằng lập luận, không dùng phần mềm.`,R`Thay $x$ bởi $2\cdot${k}-x$ đổi hai biểu thức cho nhau, nên trục đối xứng $x=${k}$. Giao điểm thỏa $x-${k}=${k}-x$, tức $(${k};1)$.`,'So hai số mũ tại giao điểm rồi xét hai hoành độ cách đều một mốc.');},
 lgDomain: s => {const a=2+s%4,k=n(s);return challenge(R`Tìm miền của $f(x)=\log_${a}(x-${k})+\log_${a}(${k+3}-x)$. Vì sao điều kiện tích hai đối số dương phải được kiểm lại với từng đối số?`,R`Cần đồng thời $x>${k}$ và $x<${k+3}$, nên miền $(${k};${k+3})$. Mỗi lôgarit yêu cầu riêng đối số dương; quy tắc gộp chỉ dùng sau khi xác nhận điều kiện này.`,'Viết hai điều kiện riêng rồi lấy giao.');},
 lgGraph: s => {const a=2+s%4,k=n(s);return challenge(R`Giải thích quan hệ giữa đồ thị $y=\log_${a}(x-${k})$ và $y=${a}^x+${k}$. Tìm điểm trên mỗi đồ thị ứng với giá trị lôgarit bằng $1$.`,R`Hai hàm ngược nhau nên đồ thị đối xứng qua $y=x$. Điểm $(${k+a};1)$ trên đồ thị lôgarit tương ứng $(1;${k+a})$ trên đồ thị mũ.`,'Đổi vai trò đầu vào và đầu ra để tìm hàm ngược.');},
 exIneq: s => {const a=2+s%4,k=n(s);return challenge(R`Giải $(1/${a})^{x^2}<(1/${a})^{${k*k}}$. Giải thích vì sao đổi chiều khi so số mũ nhưng không tự đổi chiều lần nữa khi lấy căn.`,R`Cơ số dưới một nên $x^2>${k*k}$. Suy ra $x<-${k}$ hoặc $x>${k}$. Đây là bất đẳng thức về trị tuyệt đối $|x|>${k}$, không phải chỉ $x>${k}$.`,'Sau khi so số mũ, xét hai miền âm và dương của biến.');},
 lgIneq: s => {const a=2+s%4,k=n(s);return challenge(R`Giải $\log_{1/${a}}(x-${k})\ge0$. Nêu rõ hai đầu của khoảng nghiệm có được nhận hay không.`,R`Điều kiện $x>${k}$. Vì cơ số dưới một, $x-${k}\le1$. Tập nghiệm $(${k};${k+1}]$: đầu trái bị loại do đối số bằng không, đầu phải được nhận do lôgarit bằng không.`,'Kết hợp miền xác định với kết quả từ hàm nghịch biến.');},
 eventSet: s => {const m=10+s%9;return challenge(R`Chọn một số trong $1,\ldots,${m}$. $A$: số chẵn, $B$: số chia hết cho $3$. Mô tả và đếm biến cố đúng một trong $A,B$ xảy ra.`,R`Đúng một gồm số chẵn không chia hết cho $3$ hoặc số chia hết cho $3$ không chẵn. Số lượng $\lfloor${m}/2\rfloor+\lfloor${m}/3\rfloor-2\lfloor${m}/6\rfloor=${Math.floor(m/2)+Math.floor(m/3)-2*Math.floor(m/6)}$.`,'Bỏ phần giao khỏi cả hai tập trước khi lấy hợp.');},
 independence: s => {const a=2+s%6,b=a+3;return challenge(R`Hai biến cố xung khắc có $P(A)=1/${a}$, $P(B)=1/${b}$. Có thể độc lập không? Giải thích bằng đẳng thức xác suất.`,R`Xung khắc cho $P(A\cap B)=0$, nhưng $P(A)P(B)=1/${a*b}>0$. Hai giá trị khác nhau, nên không độc lập.`,'Tính riêng xác suất giao và tích xác suất.');},
 disjointSum: s => {const k=2+s%6;return challenge(R`Hộp có $${k}$ bóng mỗi màu đỏ, xanh, vàng. Rút một bóng. Nếu $A$ là đỏ hoặc xanh, $B$ là xanh hoặc vàng, vì sao không được cộng trực tiếp $P(A)+P(B)$ để tính $P(A\cup B)$?`,R`$P(A)=P(B)=2/3$; giao là màu xanh, xác suất $1/3$. Hai biến cố không xung khắc. Hợp là mọi màu nên xác suất $1$, cũng bằng $2/3+2/3-1/3$.`,'Nhận diện màu bị đếm hai lần.');},
 unionProbability: s => {const a=2+s%5,b=a+2;return challenge(R`Một không gian có $${2*(a+b)}$ kết quả đồng khả năng. $A,B$ mỗi tập có $${a+b}$ phần tử, giao có $${a}$ phần tử. Tìm xác suất hợp và chỉ thuộc đúng một tập.`,R`Hợp có $${a+2*b}$ phần tử, xác suất $${frac(a+2*b,2*(a+b))}$. Đúng một có $${2*b}$ phần tử, xác suất $${frac(b,a+b)}$. Hợp chứa cả phần giao còn đúng một thì không.`,'Vẽ bốn vùng rời nhau để kiểm hai kết quả.');},
 indProduct: s => {const a=2+s%5;return challenge(R`Một phép thử có xác suất thành công $1/${a}$, lặp độc lập ba lần. Tính xác suất cả ba thành công và xác suất hai lần đầu thành công, lần cuối thất bại.`,R`Cả ba: $(1/${a})^3=1/${a**3}$. Trường hợp thứ hai: $(1/${a})^2(1-1/${a})=${frac(a-1,a**3)}$.`,'Viết đúng xác suất ở từng vị trí rồi nhân.');},
 atLeastOne: s => {const a=2+s%5;return challenge(R`Một phép thử thành công với xác suất $1/${a}$, lặp độc lập ba lần. Tính xác suất ít nhất một lần thành công. Giải thích vì sao không dùng $3/${a}$.`,R`Xác suất bằng $1-(1-1/${a})^3=${frac(a**3-(a-1)**3,a**3)}$. Ba biến cố thành công ở từng lần có thể đồng thời xảy ra, nên cộng trực tiếp bị trùng.`,'Biến cố đối gồm cả ba lần thất bại.');},
 exactlyOne: s => {const a=2+s%5;return challenge(R`Lặp độc lập ba lần một phép thử có xác suất thành công $1/${a}$. Tính xác suất đúng một lần thành công, phân biệt với ít nhất một.`,R`Có ba vị trí thành công, mỗi trường hợp xác suất $(1/${a})(1-1/${a})^2$. Tổng $${frac(3*(a-1)**2,a**3)}$. Các trường hợp xung khắc; ít nhất một còn gồm hai hoặc ba thành công.`,'Tách theo vị trí của lần thành công duy nhất.');},
 volumePyramid: s => {const a=n(s),h=2+s%5;return challenge(R`Một khối chóp có diện tích đáy $${3*a}$ cm$^2$, cao $${h}$ cm. Mặt phẳng song song đáy đi qua trung điểm mọi cạnh bên cắt ra chóp nhỏ ở đỉnh. Tính thể tích chóp nhỏ và phần còn lại.`,R`Chóp lớn có thể tích $${a*h}$ cm$^3$. Các độ dài chóp nhỏ bằng nửa, diện tích đáy bằng một phần tư, chiều cao bằng nửa; thể tích nhỏ bằng $${frac(a*h,8)}$ cm$^3$, phần còn lại $${frac(7*a*h,8)}$ cm$^3$.`,'So tỉ số diện tích đáy và chiều cao riêng, rồi nhân.');},
 volumePrism: s => {const a=n(s),b=2+s%5,h=3+s%4;return challenge(R`Một lăng trụ xiên có diện tích đáy $${a*b}$ cm$^2$, khoảng cách hai đáy $${h}$ cm, cạnh bên $${h+2}$ cm. Tính thể tích; chỉ ra dữ kiện thừa và giải thích.`,R`Chiều cao là khoảng cách hai đáy $${h}$ cm, nên $V=${a*b*h}$ cm$^3$. Cạnh bên xiên $${h+2}$ cm không thay chiều cao và không cần dùng.`,'Chọn đoạn vuông góc giữa hai đáy làm chiều cao.');},
};
for (const [id, question] of Object.entries(extensionQuestions)) {
 const normal = bank[id].question;
 bank[id].question = (s,d) => d === 3 ? question(s) : normal(s,d);
}

