 200:['projectionPerp','linePlaneAngle'],201:['planeAngle','planePerp'],202:['dihedral','specialPrism'],203:['eventSet','disjointSum'],204:['unionProbability','independence'],205:['indProduct','atLeastOne'],208:['exactlyOne','lgIneq'],
 211:['lgEq','exIneq'],212:['linePlanePerp','dihedral'],213:['unionProbability','exactlyOne'],
