 241:['exEq','lgEq'],242:['exIneq','lgIneq'],243:['derivativeMeaning','derivativePractice'],244:['eventSet','independence'],245:['disjointSum','unionProbability'],246:['indProduct','exactlyOne'],
 249:['lineAngle','linePlanePerp'],250:['projectionPerp','linePlaneAngle'],251:['planePerp','dihedral'],252:['specialPrism','distanceParallel'],253:['distancePoint','distanceCombined'],254:['distanceSkew','volumePyramid'],
