const entries=[];
let gameIndex=0;
for(const period of ppct.lessons) {
 if(period.kind==='assessment')continue;
 let ids=plan[period.period],eligible=[];
 if(period.kind==='elective') {
  const allowed=new Set(ppct.practice_scopes.find(scope=>scope.week===period.week).prior_week_lesson_ids);
  eligible=[...intro].filter(([,row])=>row.week<period.week&&allowed.has(row.id)).map(([id])=>id);
  const priorHki=eligible.filter(id=>hkiIds.includes(id)),priorHkii=eligible.filter(id=>Object.hasOwn(hk,id));
  const autoHki=priorHki.filter(id=>[1,2].every(depth=>bank[id].question(211,depth).type==='closed'));
  assert.ok(priorHki.length>=2);
  assert.ok(autoHki.length);
  const first=autoHki[(gameIndex*7)%autoHki.length];
  const second=priorHkii.length?priorHkii[(gameIndex*5)%priorHkii.length]:priorHki[(gameIndex*7+23)%priorHki.length];
  ids=[first,second===first?priorHki[(priorHki.indexOf(first)+1)%priorHki.length]:second];assert.equal(new Set(ids).size,2);gameIndex++;
 }
 assert.ok(ids?.length&&ids.length<=2,`Missing or oversized mapping for ${period.period}`);
 for(const id of ids)assert.ok(intro.get(id).row<=period.row,`Future concept ${id} at ${period.period}`);
 try { entries.push(buildLesson(period,ids,eligible)); }
 catch(error) { console.error(`G11 authoring failed at period ${period.period}: ${ids.join(', ')}`); throw error; }
}

function makeExam(id,title,periodNumbers,conceptPairs) {
 const examPeriods=ppct.lessons.filter(row=>periodNumbers.includes(row.period));
 assert.equal(examPeriods.length,2);assert.ok(examPeriods.every(row=>row.kind==='assessment'));
 const sourcePeriodIds=[...new Set(conceptPairs.flat().map(key=>intro.get(key).id))];
 assert.ok(sourcePeriodIds.every(sourceId=>allPeriods.get(sourceId).row<examPeriods[0].row));
 const questions=conceptPairs.map((pair,index)=>{
  const parts=pair.map((key,j)=>bank[key].question(3001+index*43+j*17,1));
  return {id:`q${index+1}`,section:'I',label:`Câu ${index+1}`,type:'essay',points:1,
   text:parts.map((part,j)=>`${j===0?'a':'b'}) ${part.prompt}`).join('\n'),
   solution:parts.map((part,j)=>`${j===0?'a':'b'}) ${part.solution}`).join('\n'),
   rubric:parts.map((part,j)=>`${j===0?'a':'b'}) 0,25 điểm cho điều kiện/phương pháp phù hợp; 0,25 điểm cho lập luận, kết quả và đơn vị đúng. ${part.evaluation.rubric?.criteria.join(' ')||'Cách giải khác đúng vẫn nhận điểm.'}`).join('\n'),conceptIds:pair};
 });
 assert.equal(questions.length,10);
 const exam=normalizeExamInput({title,durationMin:80,settings:{review:'after_close',showResult:'none',shuffleQuestions:false,shuffleOptions:false},questions});
 assert.equal(exam.questions.reduce((sum,q)=>sum+q.points,0),10);
 const stem=`tasks/r23-hkii/g11-exams/${id}`;
 const questionText=[title,'BẢN NHÁP - ĐỀ TỰ SOẠN, CẦN GIÁO VIÊN DUYỆT','Thời gian làm bài: 80 phút. Tổng điểm: 10.','PHẦN I. TỰ LUẬN (10 điểm)','Mỗi câu 1 điểm; mỗi ý a, b 0,5 điểm. Trình bày điều kiện và cách làm trong bài; đơn vị theo yêu cầu từng câu.',...questions.map((q,i)=>`Câu ${i+1}. (1 điểm)\n${q.text}`),'HẾT'].join('\n\n');
 const parsed=parseExamLines(questionText.split(/\r?\n/).map(text=>({text})));
 assert.equal(parsed.questions.length,10);assert.equal(parsed.durationMin,80);
 assert.ok(parsed.questions.every(q=>q.type==='essay'));
 const teacherSolutions=['HƯỚNG DẪN CHẤM - CHỈ DÀNH CHO GIÁO VIÊN',title,'Đề mới theo PPCT, chưa phải đề chính thức hay ma trận được trường duyệt. Đối soát cách giải, thời lượng và độ phủ trước khi dùng.',...questions.map(q=>`${q.label}\n${q.solution}\n${q.rubric}`)].join('\n\n');
 writeFileSync(new URL(stem+'.json',base),JSON.stringify(exam,null,2)+'\n');
 writeFileSync(new URL(stem+'.txt',base),questionText+'\n');
 writeFileSync(new URL(stem+'-solutions.txt',base),teacherSolutions+'\n');
 return {id,title,grade:11,week:examPeriods[0].week,minutes:80,periods:periodNumbers,sourcePeriodIds:examPeriods.map(row=>row.id),status:'draft',mode:'exam',requiresTeacherReview:true,files:{normalizedExam:stem+'.json',questionText:stem+'.txt',teacherSolutions:stem+'-solutions.txt'},conceptPairs,scopeSourcePeriodIds:sourcePeriodIds,blueprint:conceptPairs.map((pair,i)=>({question:i+1,conceptIds:pair,points:1,plannedMinutes:8})),notes:['Thời lượng 80 phút từ hai tiết kiểm tra, mỗi tiết 40 phút; không suy ngày thi từ lịch cũ.','Ma trận này do tác giả đề xuất; không có đề hoặc ma trận chính thức trong nguồn PPCT.','Dùng luồng /exams; giữ lời giải chỉ dành cho GV.']};
}
